import { useState } from 'react';
import { Settings, Activity, ChevronRight, Zap } from 'lucide-react';
import { AgentStatusBadge } from './AgentStatusBadge';

interface TimelineItem {
  id: string;
  timestamp: string;
  type: 'step' | 'event';
  step_number?: number;
  step_type?: string;
  status?: string;
  latency_ms?: number;
  error?: string;
  event_type?: string;
  payload?: any;
}

export function AgentRunTimelineComponent({ items }: { items: TimelineItem[] }) {
  const [expandedItems, setExpandedItems] = useState<Record<string, boolean>>({});

  const toggleExpand = (id: string) => {
    setExpandedItems(prev => ({ ...prev, [id]: !prev[id] }));
  };

  return (
    <div className="space-y-6">
      {items.map((item, idx) => (
        <div key={item.id || idx} className="relative pl-8 before:absolute before:left-[11px] before:top-2 before:bottom-[-24px] before:w-[2px] before:bg-border last:before:hidden">
          <div className={`absolute left-0 top-1 w-6 h-6 rounded-full flex items-center justify-center border-2 border-background shadow-sm ${
            item.type === 'step' ? (
              item.status === 'success' ? 'bg-green-500 text-white' : 'bg-destructive text-white'
            ) : 'bg-primary text-white'
          }`}>
            {item.type === 'step' ? (
              item.step_type === 'tool_call' ? <Settings size={12} /> : 
              item.step_type === 'model_call' ? <Zap size={12} /> :
              <ChevronRight size={12} />
            ) : <Activity size={12} />}
          </div>

          <div>
            <div className="flex items-center gap-3 mb-1 cursor-pointer select-none" onClick={() => toggleExpand(item.id || String(idx))}>
              <h4 className="font-bold text-foreground text-sm hover:text-primary transition-colors">
                {item.type === 'step' ? `Step ${item.step_number}: ${item.step_type}` : `Event: ${item.event_type}`}
              </h4>
              <span className="text-[10px] font-mono text-muted-foreground">{new Date(item.timestamp).toLocaleTimeString()}</span>
              {item.status && <AgentStatusBadge status={item.status} />}
            </div>

            {item.type === 'step' && (
              <div className="text-xs text-muted-foreground flex gap-4">
                {item.latency_ms && <span>Latency: {item.latency_ms}ms</span>}
              </div>
            )}

            {item.error && (
              <div className="mt-2 p-3 bg-destructive/5 border border-destructive/10 rounded-xl text-destructive text-xs font-mono">
                {item.error}
              </div>
            )}

            {expandedItems[item.id || String(idx)] && item.payload && (
              <div className="mt-2">
                <div className="flex justify-between items-center bg-secondary/50 px-3 py-1.5 rounded-t-xl border border-border border-b-0">
                  <span className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">Payload</span>
                </div>
                <pre className="p-3 bg-secondary/20 rounded-b-xl border border-border text-[10px] font-mono overflow-x-auto whitespace-pre-wrap max-h-64 overflow-y-auto">
                  {/* Note: Sensitive data should be redacted at the API level or masked here based on RBAC */}
                  {JSON.stringify(item.payload, null, 2)}
                </pre>
              </div>
            )}
          </div>
        </div>
      ))}

      {items.length === 0 && (
        <div className="text-center p-8 text-muted-foreground italic border border-dashed border-border rounded-xl">
          Nenhuma atividade registrada na timeline.
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Activity, Ban, CheckCircle, Clock, AlertTriangle, Shield } from 'lucide-react';

interface AgentStatusBadgeProps {
  status: string;
}

export function AgentStatusBadge({ status }: AgentStatusBadgeProps) {
  const normalizedStatus = status.toLowerCase();

  if (['active', 'completed', 'approved'].includes(normalizedStatus)) {
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-black uppercase tracking-wider bg-green-500/10 text-green-600">
        <CheckCircle className="w-3.5 h-3.5" />
        {status}
      </span>
    );
  }

  if (['failed', 'rejected', 'cancelled', 'denied'].includes(normalizedStatus)) {
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-black uppercase tracking-wider bg-destructive/10 text-destructive">
        <Ban className="w-3.5 h-3.5" />
        {status}
      </span>
    );
  }

  if (['running', 'executing'].includes(normalizedStatus)) {
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-black uppercase tracking-wider bg-primary/10 text-primary animate-pulse">
        <Activity className="w-3.5 h-3.5" />
        {status}
      </span>
    );
  }

  if (['waiting_approval', 'pending_approval', 'review'].includes(normalizedStatus)) {
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-black uppercase tracking-wider bg-yellow-500/10 text-yellow-600">
        <Shield className="w-3.5 h-3.5" />
        {status}
      </span>
    );
  }

  // Default / Pending / Draft
  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-black uppercase tracking-wider bg-secondary text-muted-foreground">
      <Clock className="w-3.5 h-3.5" />
      {status}
    </span>
  );
}

import React from 'react';
import { Database, Search, Download, Trash2, Eye } from 'lucide-react';

interface MemoryItem {
  id: string;
  type: string;
  summary?: string;
  content?: string;
  created_at: string;
}

export function MemoryAccessTable({ items }: { items: MemoryItem[] }) {
  if (!items || items.length === 0) {
    return (
      <div className="text-center p-10 border border-dashed border-border rounded-xl">
        <Database className="w-8 h-8 text-muted-foreground mx-auto mb-3 opacity-50" />
        <p className="text-muted-foreground font-medium">Nenhum item de memória registrado.</p>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto bg-card border border-border rounded-xl shadow-sm">
      <table className="w-full text-left border-collapse">
        <thead>
          <tr className="bg-secondary/30 text-muted-foreground text-[10px] font-black uppercase tracking-widest border-b border-border">
            <th className="px-4 py-3">ID</th>
            <th className="px-4 py-3">Tipo</th>
            <th className="px-4 py-3">Resumo / Conteúdo (Redigido)</th>
            <th className="px-4 py-3">Data</th>
            <th className="px-4 py-3 text-right">Ações</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-border">
          {items.map((item) => (
            <tr key={item.id} className="hover:bg-secondary/50 transition-colors">
              <td className="px-4 py-3 font-mono text-xs">{item.id.slice(0, 8)}...</td>
              <td className="px-4 py-3">
                <span className="text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-tighter bg-primary/10 text-primary">
                  {item.type}
                </span>
              </td>
              <td className="px-4 py-3 text-sm max-w-xs truncate">
                {item.summary || item.content || 'Conteúdo sensível / Oculto'}
              </td>
              <td className="px-4 py-3 text-xs text-muted-foreground">
                {new Date(item.created_at).toLocaleString()}
              </td>
              <td className="px-4 py-3 text-right space-x-2">
                <button className="p-1.5 text-muted-foreground hover:text-primary hover:bg-primary/10 rounded transition-colors" title="Visualizar Detalhes">
                  <Eye size={16} />
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import React from 'react';
import { Shield, ShieldAlert, ShieldCheck, HelpCircle } from 'lucide-react';

interface PolicyDecision {
  name: string;
  status: string; // active, disabled, evaluating
}

export function PolicyDecisionPanel({ policies }: { policies: PolicyDecision[] }) {
  if (!policies || policies.length === 0) {
    return (
      <div className="text-sm text-muted-foreground italic p-4 bg-secondary/30 rounded-xl border border-border">
        Nenhuma política de governança aplicada ativamente.
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {policies.map((policy, idx) => (
        <div key={idx} className="flex items-center justify-between p-3 bg-card border border-border rounded-xl shadow-sm">
          <div className="flex items-center gap-3">
            {policy.status === 'active' ? (
               <ShieldCheck className="w-5 h-5 text-green-500" />
            ) : policy.status === 'evaluating' ? (
               <HelpCircle className="w-5 h-5 text-yellow-500" />
            ) : (
               <ShieldAlert className="w-5 h-5 text-muted-foreground" />
            )}
            <span className="font-bold text-sm text-foreground">{policy.name}</span>
          </div>
          <span className={`text-[10px] font-black uppercase tracking-widest px-2 py-0.5 rounded ${
            policy.status === 'active' ? 'bg-green-500/10 text-green-600' : 
            policy.status === 'evaluating' ? 'bg-yellow-500/10 text-yellow-600' :
            'bg-secondary text-muted-foreground'
          }`}>
            {policy.status}
          </span>
        </div>
      ))}
    </div>
  );
}

import { cva, type VariantProps } from "class-variance-authority";
import type { HTMLAttributes } from "react";
import { cn } from "../lib/utils";

export const badgeVariants = cva(
  "inline-flex items-center rounded-full border font-bold uppercase tracking-wider transition-colors",
  {
    variants: {
      tone: {
        neutral: "border-border bg-secondary text-muted-foreground",
        info: "border-accent/20 bg-accent/10 text-accent",
        success: "border-primary/20 bg-primary/10 text-primary",
        warning: "border-amber-500/20 bg-amber-500/10 text-amber-700 dark:text-amber-300",
        danger: "border-destructive/20 bg-destructive/10 text-destructive",
      },
      size: {
        sm: "px-2 py-0.5 text-[10px]",
        md: "px-2.5 py-1 text-[11px]",
        lg: "px-3 py-1.5 text-xs",
      },
    },
    defaultVariants: {
      tone: "neutral",
      size: "md",
    },
  }
);

export interface BadgeProps
  extends HTMLAttributes<HTMLSpanElement>,
    VariantProps<typeof badgeVariants> {
  variant?: 'default' | 'secondary' | 'destructive' | 'outline'
}

function mapVariantToTone(variant?: BadgeProps['variant']): BadgeProps['tone'] {
  if (variant === 'default') return 'success'
  if (variant === 'secondary') return 'neutral'
  if (variant === 'destructive') return 'danger'
  if (variant === 'outline') return 'info'
  return undefined
}

export function Badge({ className, tone, size, variant, ...props }: BadgeProps) {
  return <span className={cn(badgeVariants({ tone: tone ?? mapVariantToTone(variant), size, className }))} {...props} />;
}

import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";
import { cn } from "../lib/utils";
import { Loader2 } from "lucide-react";

const buttonVariants = cva(
  "inline-flex items-center justify-center rounded-xl text-sm font-bold transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 disabled:opacity-50 disabled:pointer-events-none",
  {
    variants: {
      variant: {
        primary: "bg-primary text-white shadow-lg shadow-primary/20 hover:bg-primary/90",
        secondary: "bg-secondary text-foreground hover:bg-secondary/80",
        destructive: "bg-destructive text-white shadow-lg shadow-destructive/20 hover:bg-destructive/90",
        outline: "border border-border bg-card hover:bg-secondary hover:text-foreground",
        ghost: "hover:bg-secondary hover:text-foreground",
        accent: "bg-accent text-white shadow-lg shadow-accent/20 hover:bg-accent/90",
      },
      size: {
        sm: "h-9 px-4 py-2 text-xs",
        md: "h-11 px-6 py-2.5",
        lg: "h-14 px-8 py-3 text-lg",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "primary",
      size: "md",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  isLoading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, isLoading, children, ...props }, ref) => {
    return (
      <button
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        disabled={isLoading || props.disabled}
        {...props}
      >
        {isLoading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
        {children}
      </button>
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };

import * as React from "react"
import { cn } from "../lib/utils"

export interface LabelProps extends React.LabelHTMLAttributes<HTMLLabelElement> {}

export const Label = React.forwardRef<HTMLLabelElement, LabelProps>(
  ({ className, children, ...props }, ref) => {
    return (
      <label
        ref={ref}
        className={cn(
          "block text-sm font-semibold text-foreground mb-1",
          className,
        )}
        {...props}
      >
        {children}
      </label>
    )
  },
)

Label.displayName = "Label"

import { useLocation, Link } from 'react-router-dom'
import {
  ChevronRight,
  ChevronDown,
} from 'lucide-react'
import { buildSidebarGroups, type RouteConfig, type SidebarGroup, type RouteStatus } from '../../routes/adminRoutes'
import type { ReactNode } from 'react'

interface SidebarProps {
  collapsed?: boolean
  onNavigate?: () => void
}

function isRouteDisabled(status: RouteStatus): boolean {
  return status === 'coming_soon' || status === 'disabled'
}

function SidebarSection({ group, onNavigate }: { group: SidebarGroup; onNavigate?: () => void }) {
  const location = useLocation()
  const routes = group.items

  if (routes.length === 0) return null

  const isActive = routes.some(r => location.pathname === r.path || (r.path !== '/' && location.pathname.startsWith(r.path)))

  // Single route -> flat link
  if (routes.length === 1) {
    const route = routes[0]
    const Icon = route.icon
    const disabled = isRouteDisabled(route.status)
    return (
      <Link
        to={disabled ? '#' : route.path}
        onClick={e => { if (disabled) e.preventDefault(); onNavigate?.() }}
        className={`
          flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-medium transition-all
          ${isActive ? 'bg-primary/10 text-primary' : disabled ? 'text-muted-foreground/50 cursor-not-allowed' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}
        `}
      >
        <Icon size={16} />
        <span className="flex-1">{route.label}</span>
        {route.status === 'coming_soon' && (
          <span className="text-[8px] font-bold uppercase px-1.5 py-0.5 bg-muted rounded text-muted-foreground">Soon</span>
        )}
        {route.status === 'beta' && (
          <span className="text-[8px] font-bold uppercase px-1.5 py-0.5 bg-primary/10 text-primary rounded">Beta</span>
        )}
      </Link>
    )
  }

  // Multiple routes -> collapsible group
  return (
    <details open={isActive} className="group">
      <summary className={`
        flex items-center gap-3 px-3 py-2 rounded-lg text-sm font-semibold cursor-pointer transition-all list-none
        ${isActive ? 'text-primary' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}
      `}>
        <group.icon size={16} />
        <span className="flex-1">{group.label}</span>
        <ChevronDown size={14} className="opacity-50 group-open:rotate-180 transition-transform" />
      </summary>
      <div className="ml-4 mt-0.5 space-y-0.5 border-l border-border pl-3">
        {routes.map(route => {
          const Icon = route.icon
          const isActiveRoute = location.pathname === route.path
          const disabled = isRouteDisabled(route.status)
          return (
            <Link
              key={route.path}
              to={disabled ? '#' : route.path}
              onClick={e => { if (disabled) e.preventDefault(); onNavigate?.() }}
              className={`
                flex items-center gap-2 px-2.5 py-1.5 rounded-md text-sm transition-all
                ${isActiveRoute ? 'bg-primary/10 text-primary font-medium' : disabled ? 'text-muted-foreground/50 cursor-not-allowed' : 'text-muted-foreground hover:bg-secondary hover:text-foreground'}
              `}
            >
              <Icon size={14} />
              <span className="flex-1">{route.label}</span>
              {route.status === 'coming_soon' && (
                <span className="text-[8px] font-bold uppercase px-1 py-0.5 bg-muted rounded text-muted-foreground">Soon</span>
              )}
              {route.status === 'beta' && (
                <span className="text-[8px] font-bold uppercase px-1 py-0.5 bg-primary/10 text-primary rounded">Beta</span>
              )}
            </Link>
          )
        })}
      </div>
    </details>
  )
}

export function Sidebar({ onNavigate }: SidebarProps) {
  const groups = buildSidebarGroups()
  return (
    <nav className="flex-1 space-y-1 overflow-y-auto px-2 py-2">
      {groups.map(group => (
        <SidebarSection key={group.key} group={group} onNavigate={onNavigate} />
      ))}
    </nav>
  )
}

import { useState, useEffect } from "react"
import { 
  Box, 
  Users, 
  Key, 
  MessageSquare, 
  Cloud, 
  ArrowRight, 
  CheckCircle2, 
  Loader2,
  AlertCircle
} from "lucide-react"
import api from "../lib/api"

interface Step {
  id: number
  title: string
  description: string
  icon: React.ReactNode
}

const STEPS: Step[] = [
  { 
    id: 1, 
    title: "Modelo GGUF", 
    description: "Carregue seu primeiro modelo local para inferência otimizada.",
    icon: <Box className="w-6 h-6" />
  },
  { 
    id: 2, 
    title: "Primeiro Cliente", 
    description: "Crie um tenant para organizar seus acessos e quotas.",
    icon: <Users className="w-6 h-6" />
  },
  { 
    id: 3, 
    title: "Chave de API", 
    description: "Gere credenciais para integração com suas aplicações.",
    icon: <Key className="w-6 h-6" />
  },
  { 
    id: 4, 
    title: "Teste de Chat", 
    description: "Valide se tudo está funcionando com uma requisição real.",
    icon: <MessageSquare className="w-6 h-6" />
  },
  { 
    id: 5, 
    title: "Provedores Cloud", 
    description: "Opcional: Conecte-se a providers externos como OpenAI ou Anthropic.",
    icon: <Cloud className="w-6 h-6" />
  }
]

export function OnboardingWizard() {
  const [isVisible, setIsVisible] = useState(false)
  const [currentStep, setCurrentStep] = useState(1)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [data, setData] = useState<any>({
    clientId: null,
    apiKey: null,
    modelId: null
  })

  useEffect(() => {
    const checkStatus = async () => {
      try {
        const res = await api.get("/admin/onboarding/status")
        if (!res.data.is_finished) {
          setIsVisible(true)
        }
      } catch (e) {
        // If endpoint fails or doesn't exist, don't show wizard by default
        setIsVisible(false)
      }
    }
    checkStatus()
  }, [])

  const finishOnboarding = async () => {
    try {
      await api.post("/admin/onboarding/status", { is_finished: true })
      setIsVisible(false)
    } catch (e) {
      setIsVisible(false)
    }
  }

  const handleNext = async () => {
    setError(null)
    setIsLoading(true)
    try {
      if (currentStep === 1) {
        // Step 1: Just list models and pick the first one or a default
        const res = await api.get("/admin/models")
        if (res.data && res.data.length > 0) {
          const model = res.data[0]
          await api.post("/admin/models/runtime/load", {
            model_id: model.id,
            backend_id: model.inference_backend_id,
            model_path: model.model_file
          })
          setData({ ...data, modelId: model.model_id })
        }
      } else if (currentStep === 2) {
        // Step 2: Create first client
        const res = await api.post("/admin/clients", {
          name: "Onboarding Client",
          description: "Created during initial setup"
        })
        setData({ ...data, clientId: res.data.id })
      } else if (currentStep === 3) {
        // Step 3: Create API Key
        const res = await api.post("/admin/api-keys", {
          client_id: data.clientId,
          name: "Default Key"
        })
        setData({ ...data, apiKey: res.data.api_key })
      } else if (currentStep === 4) {
        // Step 4: Test Chat
        // This is a test, we don't need to store result
        await api.post("/v1/chat/completions", {
          model: data.modelId || "default",
          messages: [{ role: "user", content: "Olá!" }],
          max_tokens: 10
        }, {
          headers: { "Authorization": `Bearer ${data.apiKey}` }
        })
      }

      if (currentStep < STEPS.length) {
        setCurrentStep(currentStep + 1)
      } else {
        await finishOnboarding()
      }
    } catch (e: any) {
      setError(e.response?.data?.detail || "Ocorreu um erro nesta etapa.")
    } finally {
      setIsLoading(false)
    }
  }

  if (!isVisible) return null

  const activeStep = STEPS.find(s => s.id === currentStep)!

  return (
    <div className="fixed inset-0 z-[200] bg-background/95 backdrop-blur-md flex items-center justify-center p-4">
      <div className="max-w-2xl w-full bg-card border border-border rounded-[2rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]">
        {/* Progress Bar */}
        <div className="h-1.5 w-full bg-secondary">
          <div 
            className="h-full bg-primary transition-all duration-500" 
            style={{ width: `${(currentStep / STEPS.length) * 100}%` }}
          />
        </div>

        <div className="p-8 md:p-12 overflow-y-auto flex-1">
          <div className="flex items-center gap-4 mb-8">
            <div className="p-4 bg-primary/10 text-primary rounded-2xl">
              {activeStep.icon}
            </div>
            <div>
              <div className="text-xs font-bold text-primary uppercase tracking-widest mb-1">Passo {currentStep} de {STEPS.length}</div>
              <h2 className="text-3xl font-black text-foreground">{activeStep.title}</h2>
            </div>
          </div>

          <p className="text-lg text-muted-foreground leading-relaxed mb-8">
            {activeStep.description}
          </p>

          {error && (
            <div className="p-4 bg-destructive/10 text-destructive rounded-xl flex items-start gap-3 mb-8 border border-destructive/20">
              <AlertCircle className="w-5 h-5 shrink-0 mt-0.5" />
              <p className="text-sm font-medium">{error}</p>
            </div>
          )}

          {currentStep === 3 && data.apiKey && (
            <div className="p-4 bg-secondary rounded-xl mb-8 border border-border">
              <label className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest mb-2 block">Sua Nova Chave</label>
              <code className="text-sm font-mono break-all text-primary">{data.apiKey}</code>
              <p className="text-[10px] text-muted-foreground mt-2 italic">Salve esta chave, ela não será exibida novamente.</p>
            </div>
          )}
        </div>

        <div className="p-8 border-t border-border bg-secondary/30 flex items-center justify-between gap-4">
          <button 
            onClick={finishOnboarding}
            className="text-sm font-bold text-muted-foreground hover:text-foreground transition-colors"
          >
            Pular Onboarding
          </button>

          <div className="flex gap-3">
            <button 
              disabled={isLoading}
              onClick={handleNext}
              className="bg-primary hover:bg-primary/90 text-primary-foreground px-8 py-3 rounded-2xl font-bold flex items-center gap-2 transition-all shadow-lg shadow-primary/20 disabled:opacity-50"
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Processando...
                </>
              ) : (
                <>
                  {currentStep === STEPS.length ? "Finalizar" : "Próximo Passo"}
                  <ArrowRight className="w-5 h-5" />
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { CheckCircle2, AlertCircle, Clock, XCircle } from 'lucide-react'

interface StatusBadgeProps {
  status: string
  label?: string
}

export default function StatusBadge({ status, label }: StatusBadgeProps) {
  const config: Record<string, { color: string, icon: any }> = {
    healthy: { color: 'bg-primary/20 text-primary', icon: CheckCircle2 },
    ready: { color: 'bg-primary/20 text-primary', icon: CheckCircle2 },
    warning: { color: 'bg-yellow-500/20 text-yellow-600', icon: AlertCircle },
    investigating: { color: 'bg-yellow-500/20 text-yellow-600', icon: Clock },
    error: { color: 'bg-destructive/20 text-destructive', icon: XCircle },
    critical: { color: 'bg-destructive/20 text-destructive', icon: XCircle },
    draining: { color: 'bg-secondary text-foreground', icon: Clock },
  }

  const { color, icon: Icon } = config[status.toLowerCase()] || { color: 'bg-secondary text-muted-foreground', icon: Clock }

  return (
    <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${color}`}>
      <Icon className="w-3.5 h-3.5" />
      {label || status}
    </span>
  )
}

import * as React from "react"
import type { ColumnDef, ColumnFiltersState, SortingState, VisibilityState } from "@tanstack/react-table"
import {
  flexRender,
  getCoreRowModel,
  getFacetedRowModel,
  getFacetedUniqueValues,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from "@tanstack/react-table"
import { 
  ChevronDown, 
  ChevronUp, 
  ChevronsUpDown, 
  Maximize2, 
  Minimize2, 
  Download,
  Filter,
  FileJson,
  FileSpreadsheet
} from "lucide-react"
import { cn } from "../../lib/utils"
import { TablePagination } from "./table-pagination"
import { ColumnToggle } from "./column-toggle"
import { FilterModal } from "./filter-modal"
import { toast } from "sonner"

interface AdvancedTableProps<TData, TValue> {
  id: string // For persistence
  columns: ColumnDef<TData, TValue>[]
  data: TData[]
  rowCount?: number
  isLoading?: boolean
  pagination?: {
    pageIndex: number
    pageSize: number
  }
  onPaginationChange?: (pagination: { pageIndex: number, pageSize: number }) => void
  onSortingChange?: (sorting: SortingState) => void
  onFiltersApply?: (filters: any) => void
  filterConfig?: any[]
  batchActions?: {
    label: string
    icon: React.ReactNode
    onClick: (rows: TData[]) => void
    variant?: 'default' | 'destructive'
  }[]
}

export function AdvancedTable<TData, TValue>({
  id,
  columns,
  data,
  rowCount,
  isLoading,
  pagination,
  onPaginationChange,
  onSortingChange,
  onFiltersApply,
  filterConfig = [],
  batchActions = []
}: AdvancedTableProps<TData, TValue>) {
  const [rowSelection, setRowSelection] = React.useState({})
  const [columnVisibility, setColumnVisibility] = React.useState<VisibilityState>(() => {
    const saved = localStorage.getItem(`table-cols-${id}`)
    return saved ? JSON.parse(saved) : {}
  })
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [isFullscreen, setIsFullscreen] = React.useState(false)
  const [isFilterOpen, setIsFilterOpen] = React.useState(false)

  // Selection column
  const tableColumns = React.useMemo(() => [
    {
      id: "select",
      header: ({ table }: any) => (
        <input
          type="checkbox"
          className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
          checked={table.getIsAllPageRowsSelected()}
          onChange={(e) => table.toggleAllPageRowsSelected(!!e.target.checked)}
          aria-label="Selecionar todos"
        />
      ),
      cell: ({ row }: any) => (
        <input
          type="checkbox"
          className="w-4 h-4 rounded border-border text-primary focus:ring-primary"
          checked={row.getIsSelected()}
          onChange={(e) => row.toggleSelected(!!e.target.checked)}
          aria-label="Selecionar linha"
        />
      ),
      enableSorting: false,
      enableHiding: false,
    },
    ...columns
  ], [columns])

  const table = useReactTable({
    data,
    columns: tableColumns,
    state: {
      sorting,
      columnVisibility,
      rowSelection,
      pagination,
    },
    enableRowSelection: true,
    onRowSelectionChange: setRowSelection,
    onSortingChange: (updater) => {
      const next = typeof updater === 'function' ? updater(sorting) : updater
      setSorting(next)
      onSortingChange?.(next)
    },
    onColumnVisibilityChange: (updater) => {
      const next = typeof updater === 'function' ? updater(columnVisibility) : updater
      setColumnVisibility(next)
      localStorage.setItem(`table-cols-${id}`, JSON.stringify(next))
    },
    getCoreRowModel: getCoreRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFacetedRowModel: getFacetedRowModel(),
    getFacetedUniqueValues: getFacetedUniqueValues(),
    manualPagination: true,
    manualSorting: true,
    pageCount: rowCount ? Math.ceil(rowCount / (pagination?.pageSize || 10)) : -1,
  })

  const selectedRows = table.getSelectedRowModel().rows.map(r => r.original)

  const exportData = (format: 'csv' | 'json') => {
    const dataToExport = table.getCoreRowModel().rows.map(r => r.original)
    if (format === 'json') {
      const blob = new Blob([JSON.stringify(dataToExport, null, 2)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${id}-${new Date().toISOString()}.json`
      a.click()
    } else {
      const headers = table.getAllColumns().filter(c => c.getIsVisible() && c.id !== 'select').map(c => c.id)
      const csv = [
        headers.join(','),
        ...dataToExport.map(row => headers.map(h => {
          const val = (row as any)[h]
          return typeof val === 'object' ? JSON.stringify(val) : `"${val}"`
        }).join(','))
      ].join('\n')
      const blob = new Blob([csv], { type: 'text/csv' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${id}-${new Date().toISOString()}.csv`
      a.click()
    }
    toast.success(`Exportado para ${format.toUpperCase()} com sucesso!`)
  }

  return (
    <div className={cn(
      "space-y-4",
      isFullscreen && "fixed inset-0 z-[100] bg-background p-8 overflow-auto"
    )}>
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <div className="flex items-center gap-2 min-h-[40px]">
          {selectedRows.length > 0 && (
            <div className="flex items-center gap-2 animate-in fade-in slide-in-from-left-2">
              <span className="text-sm font-bold text-primary px-3 py-1 bg-primary/10 rounded-full border border-primary/20">
                {selectedRows.length} selecionados
              </span>
              <div className="h-4 w-[1px] bg-border mx-1" />
              {batchActions.map((action, i) => (
                <button
                  key={i}
                  onClick={() => action.onClick(selectedRows)}
                  className={cn(
                    "flex items-center gap-2 px-3 py-1.5 rounded-lg text-xs font-bold transition-all",
                    action.variant === 'destructive' 
                      ? "text-destructive hover:bg-destructive/10" 
                      : "text-foreground hover:bg-secondary"
                  )}
                >
                  {action.icon}
                  {action.label}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="flex items-center gap-2">
          <div className="flex items-center bg-card border border-border rounded-xl p-1 shadow-sm">
            <button 
              onClick={() => setIsFullscreen(!isFullscreen)}
              className="p-2 hover:bg-secondary rounded-lg text-muted-foreground transition-all"
              title={isFullscreen ? "Sair da tela cheia" : "Modo tela cheia"}
            >
              {isFullscreen ? <Minimize2 size={18} /> : <Maximize2 size={18} />}
            </button>
            <div className="w-[1px] h-4 bg-border mx-1" />
            <div className="relative group">
              <button className="p-2 hover:bg-secondary rounded-lg text-muted-foreground transition-all">
                <Download size={18} />
              </button>
              <div className="absolute right-0 top-full mt-2 hidden group-hover:block w-40 bg-card border border-border rounded-xl shadow-xl z-[120] overflow-hidden">
                <button 
                  onClick={() => exportData('csv')}
                  className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold hover:bg-secondary transition-colors text-left"
                >
                  <FileSpreadsheet size={14} /> Exportar CSV
                </button>
                <button 
                  onClick={() => exportData('json')}
                  className="w-full flex items-center gap-2 px-4 py-2 text-xs font-bold hover:bg-secondary border-t border-border transition-colors text-left"
                >
                  <FileJson size={14} /> Exportar JSON
                </button>
              </div>
            </div>
            <div className="w-[1px] h-4 bg-border mx-1" />
            <ColumnToggle table={table} />
          </div>
          <button 
            onClick={() => setIsFilterOpen(true)}
            className="bg-primary text-white px-4 py-2 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all"
          >
            <Filter size={18} />
            Filtros
          </button>
        </div>
      </div>

      <FilterModal 
        isOpen={isFilterOpen}
        onClose={() => setIsFilterOpen(false)}
        filterConfig={filterConfig}
        onReset={() => onFiltersApply?.({})}
        onApply={(f) => {
          onFiltersApply?.(f)
          setIsFilterOpen(false)
        }}
      />

      <div className="bg-card border border-border rounded-2xl shadow-sm overflow-hidden relative min-h-[200px]">
        {isLoading && (
          <div className="absolute inset-0 bg-background/50 backdrop-blur-[1px] z-10 flex items-center justify-center">
            <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin" />
          </div>
        )}
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              {table.getHeaderGroups().map((headerGroup) => (
                <tr key={headerGroup.id} className="border-b border-border bg-secondary/30">
                  {headerGroup.headers.map((header) => (
                    <th key={header.id} className="px-6 py-4">
                      {header.isPlaceholder ? null : (
                        <div
                          className={cn(
                            "flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-muted-foreground",
                            header.column.getCanSort() && "cursor-pointer select-none hover:text-foreground transition-colors"
                          )}
                          onClick={header.column.getToggleSortingHandler()}
                        >
                          {flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                          {header.column.getCanSort() && (
                            <div className="flex flex-col">
                              {{
                                asc: <ChevronUp size={12} className="text-primary" />,
                                desc: <ChevronDown size={12} className="text-primary" />,
                              }[header.column.getIsSorted() as string] ?? <ChevronsUpDown size={12} className="opacity-30" />}
                            </div>
                          )}
                        </div>
                      )}
                    </th>
                  ))}
                </tr>
              ))}
            </thead>
            <tbody className="divide-y divide-border">
              {table.getRowModel().rows?.length ? (
                table.getRowModel().rows.map((row) => (
                  <tr
                    key={row.id}
                    data-state={row.getIsSelected() && "selected"}
                    className={cn(
                      "hover:bg-secondary/20 transition-colors group",
                      row.getIsSelected() && "bg-primary/5"
                    )}
                  >
                    {row.getVisibleCells().map((cell) => (
                      <td key={cell.id} className="px-6 py-4">
                        {flexRender(cell.column.columnDef.cell, cell.getContext())}
                      </td>
                    ))}
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={tableColumns.length} className="h-40 text-center text-muted-foreground">
                    <div className="flex flex-col items-center gap-2">
                      <div className="p-3 bg-secondary rounded-full">
                        <Filter className="w-6 h-6 opacity-20" />
                      </div>
                      <p className="font-medium">Nenhum resultado encontrado.</p>
                      <button 
                        onClick={() => onFiltersApply?.({})}
                        className="text-xs text-primary font-bold hover:underline"
                      >
                        Limpar todos os filtros
                      </button>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      <TablePagination 
        table={table} 
        onPaginationChange={onPaginationChange}
      />
    </div>
  )
}

import * as React from "react"
import { X, Calendar as CalendarIcon, Search } from "lucide-react"
import { cn } from "../../lib/utils"

interface FilterModalProps {
  isOpen: boolean
  onClose: () => void
  onApply: (filters: any) => void
  onReset: () => void
  filterConfig: {
    id: string
    label: string
    type: 'text' | 'select' | 'date-range' | 'status'
    options?: { label: string, value: string }[]
  }[]
}

export function FilterModal({
  isOpen,
  onClose,
  onApply,
  onReset,
  filterConfig
}: FilterModalProps) {
  const [filters, setFilters] = React.useState<Record<string, any>>({})

  if (!isOpen) return null

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />
      <div className="relative bg-card w-full max-w-lg rounded-3xl border border-border shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
        <div className="flex items-center justify-between p-6 border-b border-border bg-secondary/30">
          <div>
            <h2 className="text-xl font-bold">Filtros Avançados</h2>
            <p className="text-xs text-muted-foreground mt-1">Refine sua busca com múltiplos critérios.</p>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-secondary rounded-xl text-muted-foreground transition-all">
            <X size={20} />
          </button>
        </div>

        <div className="p-6 space-y-6 max-h-[60vh] overflow-y-auto">
          {filterConfig.map((config) => (
            <div key={config.id} className="space-y-2">
              <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">
                {config.label}
              </label>

              {config.type === 'text' && (
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                  <input
                    type="text"
                    className="w-full pl-10 pr-4 py-2 bg-background border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none transition-all"
                    placeholder={`Filtrar por ${config.label.toLowerCase()}...`}
                    value={filters[config.id] || ''}
                    onChange={(e) => setFilters({ ...filters, [config.id]: e.target.value })}
                  />
                </div>
              )}

              {config.type === 'select' && (
                <select
                  className="w-full px-4 py-2 bg-background border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none transition-all"
                  value={filters[config.id] || ''}
                  onChange={(e) => setFilters({ ...filters, [config.id]: e.target.value })}
                >
                  <option value="">Todos</option>
                  {config.options?.map(opt => (
                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                  ))}
                </select>
              )}

              {config.type === 'date-range' && (
                <div className="grid grid-cols-2 gap-2">
                  <div className="relative">
                    <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <input
                      type="date"
                      className="w-full pl-10 pr-4 py-2 bg-background border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none transition-all text-sm"
                      value={filters[`${config.id}_start`] || ''}
                      onChange={(e) => setFilters({ ...filters, [`${config.id}_start`]: e.target.value })}
                    />
                  </div>
                  <div className="relative">
                    <CalendarIcon className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                    <input
                      type="date"
                      className="w-full pl-10 pr-4 py-2 bg-background border border-border rounded-xl focus:ring-2 focus:ring-primary outline-none transition-all text-sm"
                      value={filters[`${config.id}_end`] || ''}
                      onChange={(e) => setFilters({ ...filters, [`${config.id}_end`]: e.target.value })}
                    />
                  </div>
                </div>
              )}

              {config.type === 'status' && (
                <div className="flex flex-wrap gap-2">
                  {config.options?.map(opt => {
                    const isActive = filters[config.id] === opt.value
                    return (
                      <button
                        key={opt.value}
                        onClick={() => setFilters({ ...filters, [config.id]: isActive ? null : opt.value })}
                        className={cn(
                          "px-3 py-1.5 rounded-full text-xs font-bold border transition-all",
                          isActive 
                            ? "bg-primary border-primary text-white shadow-lg shadow-primary/20" 
                            : "bg-secondary border-border text-muted-foreground hover:border-primary/50"
                        )}
                      >
                        {opt.label}
                      </button>
                    )
                  })}
                </div>
              )}
            </div>
          ))}
        </div>

        <div className="p-6 border-t border-border bg-secondary/30 flex gap-3">
          <button
            onClick={() => {
              setFilters({})
              onReset()
            }}
            className="flex-1 px-4 py-2.5 bg-secondary text-foreground rounded-xl font-bold hover:bg-secondary/80 transition-all"
          >
            Limpar
          </button>
          <button
            onClick={() => onApply(filters)}
            className="flex-2 px-8 py-2.5 bg-primary text-white rounded-xl font-bold shadow-lg shadow-primary/20 hover:bg-primary/90 transition-all"
          >
            Aplicar Filtros
          </button>
        </div>
      </div>
    </div>
  )
}

import type { Table } from "@tanstack/react-table"
import { 
  ChevronLeft, 
  ChevronRight, 
  ChevronsLeft, 
  ChevronsRight 
} from "lucide-react"
import { cn } from "../../lib/utils"

interface TablePaginationProps<TData> {
  table: Table<TData>
  onPaginationChange?: (pagination: { pageIndex: number, pageSize: number }) => void
}

export function TablePagination<TData>({
  table,
  onPaginationChange
}: TablePaginationProps<TData>) {
  return (
    <div className="flex items-center justify-between px-2">
      <div className="flex-1 text-sm text-muted-foreground">
        {table.getFilteredSelectedRowModel().rows.length} de{" "}
        {table.getFilteredRowModel().rows.length} linha(s) selecionada(s).
      </div>
      <div className="flex items-center space-x-6 lg:space-x-8">
        <div className="flex items-center space-x-2">
          <p className="text-sm font-bold">Linhas por página</p>
          <select
            value={table.getState().pagination.pageSize}
            onChange={(e) => {
              const size = Number(e.target.value)
              table.setPageSize(size)
              onPaginationChange?.({ 
                pageIndex: table.getState().pagination.pageIndex, 
                pageSize: size 
              })
            }}
            className="h-8 w-[70px] bg-card border border-border rounded-lg text-xs font-bold focus:ring-2 focus:ring-primary outline-none transition-all"
          >
            {[10, 25, 50, 100].map((pageSize) => (
              <option key={pageSize} value={pageSize}>
                {pageSize}
              </option>
            ))}
          </select>
        </div>
        <div className="flex w-[100px] items-center justify-center text-sm font-bold">
          Página {table.getState().pagination.pageIndex + 1} de{" "}
          {table.getPageCount()}
        </div>
        <div className="flex items-center space-x-2">
          <button
            className="hidden h-8 w-8 p-0 lg:flex items-center justify-center border border-border rounded-lg hover:bg-secondary disabled:opacity-50 transition-all"
            onClick={() => table.setPageIndex(0)}
            disabled={!table.getCanPreviousPage()}
          >
            <span className="sr-only">Primeira página</span>
            <ChevronsLeft size={16} />
          </button>
          <button
            className="h-8 w-8 p-0 flex items-center justify-center border border-border rounded-lg hover:bg-secondary disabled:opacity-50 transition-all"
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
          >
            <span className="sr-only">Página anterior</span>
            <ChevronLeft size={16} />
          </button>
          <button
            className="h-8 w-8 p-0 flex items-center justify-center border border-border rounded-lg hover:bg-secondary disabled:opacity-50 transition-all"
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
          >
            <span className="sr-only">Próxima página</span>
            <ChevronRight size={16} />
          </button>
          <button
            className="hidden h-8 w-8 p-0 lg:flex items-center justify-center border border-border rounded-lg hover:bg-secondary disabled:opacity-50 transition-all"
            onClick={() => table.setPageIndex(table.getPageCount() - 1)}
            disabled={!table.getCanNextPage()}
          >
            <span className="sr-only">Última página</span>
            <ChevronsRight size={16} />
          </button>
        </div>
      </div>
    </div>
  )
}

import * as React from "react"
import { useVirtualizer } from "@tanstack/react-virtual"
import { cn } from "../../lib/utils"

interface VirtualListProps<T> {
  items: T[]
  height?: string | number
  itemHeight: number
  renderItem: (item: T, index: number) => React.ReactNode
  className?: string
}

export function VirtualList<T>({
  items,
  height = "400px",
  itemHeight,
  renderItem,
  className
}: VirtualListProps<T>) {
  const parentRef = React.useRef<HTMLDivElement>(null)

  const rowVirtualizer = useVirtualizer({
    count: items.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => itemHeight,
    overscan: 5,
  })

  return (
    <div
      ref={parentRef}
      className={cn("overflow-auto border border-border rounded-xl bg-card shadow-sm", className)}
      style={{
        height: height,
        contain: "strict",
      }}
    >
      <div
        style={{
          height: `${rowVirtualizer.getTotalSize()}px`,
          width: "100%",
          position: "relative",
        }}
      >
        {rowVirtualizer.getVirtualItems().map((virtualRow) => (
          <div
            key={virtualRow.index}
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: `${virtualRow.size}px`,
              transform: `translateY(${virtualRow.start}px)`,
            }}
          >
            {renderItem(items[virtualRow.index], virtualRow.index)}
          </div>
        ))}
      </div>
    </div>
  )
}

import { createContext, useContext, useEffect, useState } from "react"

type Theme = "dark" | "light" | "system"

type ThemeProviderState = {
  theme: Theme
  setTheme: (theme: Theme) => void
}

const initialState: ThemeProviderState = {
  theme: "system",
  setTheme: () => null,
}

const ThemeProviderContext = createContext<ThemeProviderState>(initialState)

export function ThemeProvider({
  children,
  defaultTheme = "system",
  storageKey = "vite-ui-theme",
  ...props
}: {
  children: React.ReactNode
  defaultTheme?: Theme
  storageKey?: string
}) {
  const [theme, setTheme] = useState<Theme>(
    () => (localStorage.getItem(storageKey) as Theme) || defaultTheme
  )

  useEffect(() => {
    const root = window.document.documentElement

    root.classList.remove("light", "dark")

    if (theme === "system") {
      const systemTheme = window.matchMedia("(prefers-color-scheme: dark)")
        .matches
        ? "dark"
        : "light"

      root.classList.add(systemTheme)
      return
    }

    root.classList.add(theme)
  }, [theme])

  const value = {
    theme,
    setTheme: (theme: Theme) => {
      localStorage.setItem(storageKey, theme)
      setTheme(theme)
    },
  }

  return (
    <ThemeProviderContext.Provider {...props} value={value}>
      {children}
    </ThemeProviderContext.Provider>
  )
}

export const useTheme = () => {
  const context = useContext(ThemeProviderContext)

  if (context === undefined)
    throw new Error("useTheme must be used within a ThemeProvider")

  return context
}

