import { useEffect, useState, useRef, useCallback } from 'react';
import { useAuthStore } from '../store/useAuthStore';

export type StreamStatus = 'idle' | 'connecting' | 'connected' | 'reconnecting' | 'failed';

export interface StreamEvent {
  event: string;
  run_id: string;
  timestamp: string;
  data: any;
}

export function useAgentRunStream(runId?: string) {
  const [status, setStatus] = useState<StreamStatus>(runId ? 'connecting' : 'idle');
  const [events, setEvents] = useState<StreamEvent[]>([]);
  const [error, setError] = useState<string | null>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const reconnectTimeoutRef = useRef<number | null>(null);
  const retryCountRef = useRef(0);
  const maxRetries = 5;

  const token = useAuthStore((state) => state.token);

  const connect = useCallback(() => {
    if (!runId || !token) {
      setStatus(runId ? 'failed' : 'idle');
      if (runId && !token) setError('Missing auth token');
      return;
    }

    if (socketRef.current) {
      socketRef.current.close();
    }

    const isDev = window.location.port === '5173' || window.location.port === '5174';
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = isDev ? 'localhost:8080' : window.location.host;
    const url = `${protocol}//${host}/v1/agents/runs/${runId}/stream?token=${encodeURIComponent(token)}`;

    setStatus(retryCountRef.current > 0 ? 'reconnecting' : 'connecting');
    setError(null);

    const ws = new WebSocket(url);
    socketRef.current = ws;

    ws.onopen = () => {
      setStatus('connected');
      retryCountRef.current = 0;
    };

    ws.onmessage = (event) => {
      try {
        const parsed = JSON.parse(event.data);
        if (parsed.event) {
          setEvents((prev) => [...prev, parsed]);
        }
      } catch (err) {
        console.error('Error parsing WS message:', err);
      }
    };

    ws.onerror = (evt) => {
      console.error('WebSocket error:', evt);
      setError('WebSocket connection error');
    };

    ws.onclose = (evt) => {
      socketRef.current = null;

      if (evt.code === 1000) {
        setStatus('failed');
        return;
      }

      if (retryCountRef.current < maxRetries) {
        setStatus('reconnecting');
        const delay = Math.min(1000 * Math.pow(2, retryCountRef.current), 10000);
        retryCountRef.current += 1;
        reconnectTimeoutRef.current = window.setTimeout(() => {
          connect();
        }, delay);
      } else {
        setStatus('failed');
        setError('Connection failed after maximum retry attempts.');
      }
    };
  }, [runId, token]);

  useEffect(() => {
    if (!runId) {
      setStatus('failed');
      setEvents([]);
      setError(null);
      return;
    }

    retryCountRef.current = 0;
    setEvents([]);
    connect();

    return () => {
      if (socketRef.current) {
        socketRef.current.close(1000, 'Component unmounted');
      }
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [runId, connect]);

  const sendCommand = useCallback((command: 'cancel' | 'pause' | 'resume') => {
    if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({ command }));
    } else {
      console.warn('Cannot send command: WebSocket is not open.');
    }
  }, []);

  const clearLogs = useCallback(() => {
    setEvents([]);
  }, []);

  return {
    status,
    events,
    error,
    sendCommand,
    clearLogs,
  };
}
export default useAgentRunStream;

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { APIError } from './api'

describe('APIError', () => {
  it('creates error with message and status', () => {
    const err = new APIError('not found', 404, { detail: 'not found' })
    expect(err.message).toBe('not found')
    expect(err.status).toBe(404)
    expect(err.data).toEqual({ detail: 'not found' })
    expect(err.name).toBe('APIError')
  })

  it('creates error without status', () => {
    const err = new APIError('generic error')
    expect(err.message).toBe('generic error')
    expect(err.status).toBeUndefined()
  })
})

describe('api client', () => {
  beforeEach(() => {
    vi.stubGlobal('useAuthStore', {
      getState: () => ({ token: 'test-token', logout: vi.fn() })
    })
    vi.clearAllMocks()
  })

  it('exports default api instance', async () => {
    const api = (await import('./api')).default
    expect(api).toBeDefined()
    expect(typeof api.health).toBe('function')
  })

  it('sends GET request without params', async () => {
    const api = (await import('./api')).default
    const spy = vi.spyOn((api as any).client, 'request').mockResolvedValue({ data: { status: 'ok' } })

    await api.health()

    expect(spy).toHaveBeenCalledWith(expect.objectContaining({
      method: 'GET',
      url: '/health'
    }))
    expect((spy.mock.calls[0][0] as any).params).toBeUndefined()
  })

  it('sends GET request with params', async () => {
    const api = (await import('./api')).default
    const spy = vi.spyOn((api as any).client, 'request').mockResolvedValue({ data: [] })

    await api.getCostsSummary({ period: 'last_7_days' })

    const call = spy.mock.calls[0][0] as any
    expect(call.method).toBe('GET')
    expect(call.url).toBe('/api/admin/costs/summary')
    expect(call.params).toBeInstanceOf(URLSearchParams)
    expect((call.params as URLSearchParams).get('period')).toBe('last_7_days')
  })

  it('sends POST request with body', async () => {
    const api = (await import('./api')).default
    const spy = vi.spyOn((api as any).client, 'request').mockResolvedValue({ data: {} })

    await api.createModel({ name: 'test-model' })

    expect(spy).toHaveBeenCalledWith(expect.objectContaining({
      method: 'POST',
      url: '/admin/models',
      data: { name: 'test-model' }
    }))
  })

  it('handles API error correctly', async () => {
    const api = (await import('./api')).default
    vi.spyOn((api as any).client, 'request').mockRejectedValue(new APIError('Bad Request', 400))

    await expect(api.health()).rejects.toThrow('Bad Request')
  })
})

import { useState } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../lib/api'
import { 
  ShieldAlert, 
  ShieldCheck, 
  Clock, 
  XOctagon, 
  AlertTriangle, 
  Check, 
  X, 
  Eye, 
  RefreshCw, 
  ChevronRight, 
  FileText,
  User,
  SlidersHorizontal,
  ChevronDown
} from 'lucide-react'
import { toast } from 'sonner'

interface ApprovalRequest {
  id: string
  agent_run_id: string
  task_id?: string
  tool_invocation_id?: string
  risk_level: string
  reason: string
  requested_by: string
  reviewer_role: string
  status: 'pending' | 'approved' | 'rejected' | 'expired' | 'cancelled'
  expires_at: string
  sanitized_context?: any
  decision_reason?: string
  decided_by?: string
  decided_at?: string
  created_at: string
  updated_at: string
}

export default function AgentApprovals() {
  const queryClient = useQueryClient()
  const [selectedRequest, setSelectedRequest] = useState<ApprovalRequest | null>(null)
  const [statusFilter, setStatusFilter] = useState<string>('')
  const [isDecisionModalOpen, setIsDecisionModalOpen] = useState(false)
  const [decisionType, setDecisionType] = useState<'approve' | 'reject' | 'request-changes' | null>(null)
  const [decisionReason, setDecisionReason] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Fetch approval requests
  const { data: requests = [], isLoading, isRefetching, refetch } = useQuery<ApprovalRequest[]>({
    queryKey: ['agent-approvals', statusFilter],
    queryFn: async () => {
      const res = await api.get('/admin/agent-approvals', {
        params: statusFilter ? { status: statusFilter } : {}
      })
      return res.data
    }
  })

  // Mutations for approvals
  const decisionMutation = useMutation({
    mutationFn: async ({ id, type, reason }: { id: string; type: 'approve' | 'reject' | 'request-changes'; reason: string }) => {
      const endpoint = `/admin/agent-approvals/${id}/${type}`
      const res = await api.post(endpoint, { decision_reason: reason })
      return res.data
    },
    onSuccess: (data) => {
      toast.success(`Solicitação ${data.status === 'approved' ? 'aprovada' : data.status === 'rejected' ? 'rejeitada' : 'alteração solicitada'} com sucesso!`)
      queryClient.invalidateQueries({ queryKey: ['agent-approvals'] })
      setSelectedRequest(data)
      setIsDecisionModalOpen(false)
      setDecisionReason('')
      setDecisionType(null)
    },
    onError: (err: any) => {
      const detail = err.response?.data?.detail || err.message || 'Erro desconhecido'
      toast.error(`Falha na operação: ${detail}`)
    },
    onSettled: () => {
      setIsSubmitting(false)
    }
  })

  const handleDecisionSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedRequest || !decisionType) return
    setIsSubmitting(true)
    decisionMutation.mutate({
      id: selectedRequest.id,
      type: decisionType,
      reason: decisionReason
    })
  }

  const openDecisionModal = (type: 'approve' | 'reject' | 'request-changes') => {
    setDecisionType(type)
    setIsDecisionModalOpen(true)
  }

  // Format date helper
  const formatDate = (isoString?: string) => {
    if (!isoString) return '-'
    try {
      const date = new Date(isoString)
      return date.toLocaleString('pt-BR')
    } catch {
      return isoString
    }
  }

  // Risk Badge component
  const RiskBadge = ({ risk }: { risk: string }) => {
    const riskLower = risk.toLowerCase()
    let styles = "bg-slate-100 text-slate-800 border-slate-200 dark:bg-slate-900/40 dark:text-slate-300 dark:border-slate-800"
    if (riskLower === 'medium') {
      styles = "bg-amber-100/80 text-amber-800 border-amber-200 dark:bg-amber-950/20 dark:text-amber-300 dark:border-amber-900/50"
    } else if (riskLower === 'high') {
      styles = "bg-orange-100/80 text-orange-800 border-orange-200 dark:bg-orange-950/30 dark:text-orange-400 dark:border-orange-900"
    } else if (riskLower === 'critical') {
      styles = "bg-rose-100/80 text-rose-800 border-rose-200 dark:bg-rose-950/40 dark:text-rose-400 dark:border-rose-900 animate-pulse"
    }

    return (
      <span className={`inline-flex items-center gap-1 px-2.5 py-1 text-xs font-semibold rounded-full border ${styles}`}>
        <ShieldAlert className="w-3.5 h-3.5" />
        <span className="capitalize">{risk}</span>
      </span>
    )
  }

  // Status Badge component
  const StatusBadge = ({ status }: { status: string }) => {
    let styles = "bg-gray-100 text-gray-800 border-gray-200 dark:bg-gray-800 dark:text-gray-300"
    let icon = <Clock className="w-3.5 h-3.5" />

    if (status === 'pending') {
      styles = "bg-yellow-500/10 text-yellow-600 border-yellow-500/20 dark:bg-yellow-500/10 dark:text-yellow-400"
    } else if (status === 'approved') {
      styles = "bg-emerald-500/10 text-emerald-600 border-emerald-500/20 dark:bg-emerald-500/10 dark:text-emerald-400"
      icon = <ShieldCheck className="w-3.5 h-3.5" />
    } else if (status === 'rejected') {
      styles = "bg-red-500/10 text-red-600 border-red-500/20 dark:bg-red-500/10 dark:text-red-400"
      icon = <XOctagon className="w-3.5 h-3.5" />
    } else if (status === 'cancelled') {
      styles = "bg-blue-500/10 text-blue-600 border-blue-500/20 dark:bg-blue-500/10 dark:text-blue-400"
      icon = <AlertTriangle className="w-3.5 h-3.5" />
    } else if (status === 'expired') {
      styles = "bg-zinc-500/10 text-zinc-500 border-zinc-500/20 dark:bg-zinc-500/10 dark:text-zinc-400"
    }

    return (
      <span className={`inline-flex items-center gap-1.5 px-3 py-1 rounded-full border text-xs font-bold capitalize ${styles}`}>
        {icon}
        {status === 'cancelled' ? 'Alterações solicitadas' : status}
      </span>
    )
  }

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-foreground">
            Aprovações de Agentes (HITL)
          </h1>
          <p className="text-muted-foreground mt-1">
            Revise solicitações de aprovação pendentes antes de executar chamadas de ferramentas de alto risco.
          </p>
        </div>
        <button
          onClick={() => refetch()}
          disabled={isLoading || isRefetching}
          className="inline-flex items-center gap-2 self-start md:self-auto bg-card hover:bg-secondary text-foreground font-semibold px-4 py-2 border border-border rounded-xl shadow-sm transition-all duration-200 disabled:opacity-50"
        >
          <RefreshCw className={`w-4 h-4 ${(isLoading || isRefetching) ? 'animate-spin' : ''}`} />
          {isRefetching ? 'Atualizando...' : 'Atualizar'}
        </button>
      </div>

      {/* Filter and Content Area */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

        {/* Left 2 Columns: Filters & Request List */}
        <div className="lg:col-span-2 space-y-4">

          {/* Filters Bar */}
          <div className="bg-card rounded-2xl border border-border p-4 shadow-sm flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2 text-muted-foreground text-sm font-semibold shrink-0">
              <SlidersHorizontal className="w-4 h-4" />
              Filtrar por:
            </div>

            <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-none">
              {[
                { label: 'Todos', value: '' },
                { label: 'Pendentes', value: 'pending' },
                { label: 'Aprovados', value: 'approved' },
                { label: 'Rejeitados', value: 'rejected' },
                { label: 'Alterações', value: 'cancelled' },
                { label: 'Expirados', value: 'expired' }
              ].map((filter) => (
                <button
                  key={filter.value}
                  onClick={() => {
                    setStatusFilter(filter.value)
                    setSelectedRequest(null)
                  }}
                  className={`
                    px-4 py-1.5 rounded-full text-xs font-bold transition-all border shrink-0
                    ${statusFilter === filter.value 
                      ? 'bg-primary border-primary text-primary-foreground shadow-sm' 
                      : 'bg-background hover:bg-secondary text-muted-foreground border-border'}
                  `}
                >
                  {filter.label}
                </button>
              ))}
            </div>
          </div>

          {/* List of Requests */}
          <div className="bg-card rounded-2xl border border-border overflow-hidden shadow-sm">
            {isLoading ? (
              <div className="p-12 text-center text-muted-foreground flex flex-col items-center justify-center gap-3">
                <RefreshCw className="w-8 h-8 animate-spin text-primary" />
                <span className="font-semibold">Carregando solicitações de aprovação...</span>
              </div>
            ) : requests.length === 0 ? (
              <div className="p-12 text-center text-muted-foreground flex flex-col items-center justify-center gap-2">
                <ShieldCheck className="w-10 h-10 text-muted-foreground/60" />
                <h3 className="font-bold text-foreground mt-2">Nenhuma solicitação encontrada</h3>
                <p className="text-sm">Não há aprovações pendentes ou concluídas sob estes critérios.</p>
              </div>
            ) : (
              <div className="divide-y divide-border">
                {requests.map((req) => {
                  const isSelected = selectedRequest?.id === req.id
                  return (
                    <div
                      key={req.id}
                      onClick={() => setSelectedRequest(req)}
                      className={`
                        p-5 cursor-pointer transition-all duration-200 flex items-start justify-between gap-4 hover:bg-secondary/40
                        ${isSelected ? 'bg-secondary/60 border-l-4 border-primary pl-4' : ''}
                      `}
                    >
                      <div className="space-y-1.5 min-w-0">
                        <div className="flex flex-wrap items-center gap-2">
                          <RiskBadge risk={req.risk_level} />
                          <StatusBadge status={req.status} />
                        </div>
                        <h4 className="font-bold text-foreground text-sm md:text-base leading-tight truncate">
                          Run: <span className="font-mono text-xs text-muted-foreground">{req.agent_run_id}</span>
                        </h4>
                        <p className="text-xs text-muted-foreground line-clamp-2">
                          {req.reason}
                        </p>
                        <div className="text-[10px] text-muted-foreground font-semibold flex items-center gap-2">
                          <span>Por: {req.requested_by}</span>
                          <span>•</span>
                          <span>Criado: {formatDate(req.created_at)}</span>
                        </div>
                      </div>

                      <div className="shrink-0 flex items-center self-center text-muted-foreground">
                        <ChevronRight className={`w-5 h-5 transition-transform duration-200 ${isSelected ? 'translate-x-1' : ''}`} />
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </div>
        </div>

        {/* Right 1 Column: Detail Panel */}
        <div className="lg:col-span-1">
          {selectedRequest ? (
            <div className="bg-card border border-border rounded-2xl shadow-sm overflow-hidden sticky top-24 divide-y divide-border">

              {/* Detail Header */}
              <div className="p-5 space-y-3">
                <div className="flex items-center justify-between">
                  <h3 className="font-black text-foreground uppercase tracking-wider text-sm">
                    Detalhes da Solicitação
                  </h3>
                  <button 
                    onClick={() => setSelectedRequest(null)}
                    className="p-1 hover:bg-secondary rounded-lg text-muted-foreground transition-colors"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>

                <div className="space-y-1.5">
                  <div className="flex gap-2">
                    <RiskBadge risk={selectedRequest.risk_level} />
                    <StatusBadge status={selectedRequest.status} />
                  </div>
                  <div className="text-xs text-muted-foreground font-semibold">
                    ID: <span className="font-mono">{selectedRequest.id}</span>
                  </div>
                </div>
              </div>

              {/* Info Body */}
              <div className="p-5 space-y-4 text-sm">

                {/* Reason & Workflow Details */}
                <div className="space-y-1">
                  <span className="text-xs text-muted-foreground font-black uppercase">Motivo / Gatilho</span>
                  <p className="text-foreground font-medium bg-secondary/30 p-3 rounded-xl border border-border">
                    {selectedRequest.reason}
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <span className="text-[10px] text-muted-foreground font-black uppercase block">Reviewer Role</span>
                    <span className="font-bold text-foreground capitalize flex items-center gap-1 mt-0.5">
                      <User className="w-3.5 h-3.5 text-muted-foreground" />
                      {selectedRequest.reviewer_role.replace('admin_', '')}
                    </span>
                  </div>
                  <div>
                    <span className="text-[10px] text-muted-foreground font-black uppercase block">Solicitado Por</span>
                    <span className="font-bold text-foreground mt-0.5 block truncate">
                      {selectedRequest.requested_by}
                    </span>
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-1 xl:grid-cols-2 gap-3">
                  <div>
                    <span className="text-[10px] text-muted-foreground font-black uppercase block">Data de Criação</span>
                    <span className="text-xs font-semibold text-foreground mt-0.5 block">
                      {formatDate(selectedRequest.created_at)}
                    </span>
                  </div>
                  {selectedRequest.status === 'pending' ? (
                    <div>
                      <span className="text-[10px] text-muted-foreground font-black uppercase block">Expira Em</span>
                      <span className="text-xs font-semibold text-foreground mt-0.5 block flex items-center gap-1 text-orange-500">
                        <Clock className="w-3 h-3" />
                        {formatDate(selectedRequest.expires_at)}
                      </span>
                    </div>
                  ) : (
                    <div>
                      <span className="text-[10px] text-muted-foreground font-black uppercase block">Decidido Em</span>
                      <span className="text-xs font-semibold text-foreground mt-0.5 block">
                        {formatDate(selectedRequest.decided_at)}
                      </span>
                    </div>
                  )}
                </div>

                {/* Agent Run / Task ID */}
                <div className="space-y-1">
                  <span className="text-[10px] text-muted-foreground font-black uppercase block">ID da Execução (Run)</span>
                  <span className="font-mono text-xs text-foreground bg-secondary/50 px-2 py-1 rounded border border-border block select-all truncate">
                    {selectedRequest.agent_run_id}
                  </span>
                </div>

                {selectedRequest.task_id && (
                  <div>
                    <span className="text-[10px] text-muted-foreground font-black uppercase block">ID da Task</span>
                    <span className="font-mono text-xs text-foreground bg-secondary/50 px-2 py-1 rounded border border-border block truncate">
                      {selectedRequest.task_id}
                    </span>
                  </div>
                )}
              </div>

              {/* Sanitized Context Section */}
              {selectedRequest.sanitized_context && (
                <div className="p-5 space-y-2">
                  <span className="text-xs text-muted-foreground font-black uppercase flex items-center gap-1.5">
                    <FileText className="w-3.5 h-3.5" />
                    Contexto Sanitizado (Ferramenta)
                  </span>

                  <div className="bg-slate-950 text-slate-200 p-4 rounded-xl font-mono text-[11px] overflow-auto max-h-64 scrollbar-thin border border-slate-900 shadow-inner">
                    <pre className="whitespace-pre-wrap word-break-all">
                      {JSON.stringify(selectedRequest.sanitized_context, null, 2)}
                    </pre>
                  </div>
                  <p className="text-[10px] text-muted-foreground italic leading-normal">
                    * Parâmetros sensíveis (prompts, chaves) foram omitidos ou marcados como redigidos para segurança.
                  </p>
                </div>
              )}

              {/* Review History / Details */}
              {selectedRequest.status !== 'pending' && (
                <div className="p-5 bg-secondary/10 space-y-3">
                  <h4 className="font-black text-xs text-foreground uppercase tracking-wider">
                    Histórico da Decisão
                  </h4>
                  <div className="space-y-2 text-xs">
                    <div className="grid grid-cols-2 gap-2">
                      <div>
                        <span className="text-muted-foreground block text-[9px] uppercase font-bold">Decidido Por</span>
                        <span className="font-bold text-foreground">{selectedRequest.decided_by || '-'}</span>
                      </div>
                      <div>
                        <span className="text-muted-foreground block text-[9px] uppercase font-bold">Data da Decisão</span>
                        <span className="font-semibold text-foreground">{formatDate(selectedRequest.decided_at)}</span>
                      </div>
                    </div>
                    {selectedRequest.decision_reason && (
                      <div className="mt-1 bg-background/50 border border-border p-3 rounded-xl">
                        <span className="text-muted-foreground block text-[9px] uppercase font-bold mb-1">Comentários</span>
                        <p className="text-foreground leading-relaxed italic">
                          "{selectedRequest.decision_reason}"
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Review Actions Panel */}
              {selectedRequest.status === 'pending' && (
                <div className="p-5 bg-secondary/20 space-y-3">
                  <h4 className="font-black text-xs text-foreground uppercase tracking-wider">
                    Ações de Revisão
                  </h4>

                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
                    <button
                      onClick={() => openDecisionModal('approve')}
                      className="w-full bg-emerald-600 hover:bg-emerald-500 text-white font-bold py-2 px-3 rounded-xl flex items-center justify-center gap-1.5 transition-all text-xs border border-emerald-700 shadow-sm"
                    >
                      <Check className="w-3.5 h-3.5" />
                      Aprovar
                    </button>
                    <button
                      onClick={() => openDecisionModal('reject')}
                      className="w-full bg-red-600 hover:bg-red-500 text-white font-bold py-2 px-3 rounded-xl flex items-center justify-center gap-1.5 transition-all text-xs border border-red-700 shadow-sm"
                    >
                      <X className="w-3.5 h-3.5" />
                      Rejeitar
                    </button>
                    <button
                      onClick={() => openDecisionModal('request-changes')}
                      className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-2 px-3 rounded-xl flex items-center justify-center gap-1.5 transition-all text-xs border border-blue-700 shadow-sm"
                    >
                      <AlertTriangle className="w-3.5 h-3.5" />
                      Revisar
                    </button>
                  </div>
                </div>
              )}

            </div>
          ) : (
            <div className="bg-card border border-border border-dashed rounded-2xl p-8 text-center text-muted-foreground h-64 flex flex-col items-center justify-center gap-2 shadow-inner">
              <Eye className="w-8 h-8 text-muted-foreground/45" />
              <p className="font-semibold text-sm">Selecione uma solicitação</p>
              <p className="text-xs max-w-[200px] mx-auto">
                Clique em uma solicitação na lista para ver seus detalhes e realizar ações de auditoria ou aprovação.
              </p>
            </div>
          )}
        </div>

      </div>

      {/* Decision Modal */}
      {isDecisionModalOpen && selectedRequest && decisionType && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-xs animate-in fade-in duration-200">
          <div className="bg-card border border-border rounded-3xl max-w-lg w-full overflow-hidden shadow-2xl p-6 space-y-4 animate-in zoom-in-95 duration-200">

            <div className="flex items-center justify-between pb-2 border-b border-border">
              <h3 className="text-lg font-black text-foreground flex items-center gap-2">
                {decisionType === 'approve' ? (
                  <>
                    <div className="p-1.5 bg-emerald-500/10 text-emerald-500 rounded-lg">
                      <Check className="w-5 h-5" />
                    </div>
                    Confirmar Aprovação
                  </>
                ) : decisionType === 'reject' ? (
                  <>
                    <div className="p-1.5 bg-red-500/10 text-red-500 rounded-lg">
                      <X className="w-5 h-5" />
                    </div>
                    Confirmar Rejeição
                  </>
                ) : (
                  <>
                    <div className="p-1.5 bg-blue-500/10 text-blue-500 rounded-lg">
                      <AlertTriangle className="w-5 h-5" />
                    </div>
                    Solicitar Alterações
                  </>
                )}
              </h3>
              <button 
                onClick={() => {
                  setIsDecisionModalOpen(false)
                  setDecisionReason('')
                }}
                className="p-1.5 hover:bg-secondary rounded-lg text-muted-foreground transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            <p className="text-sm text-muted-foreground leading-relaxed">
              Você está prestes a{' '}
              <strong className="text-foreground">
                {decisionType === 'approve' ? 'APROVAR' : decisionType === 'reject' ? 'REJEITAR' : 'SOLICITAR ALTERAÇÕES para'}
              </strong>{' '}
              a execução do agente run{' '}
              <code className="bg-secondary/60 px-1 py-0.5 rounded font-mono text-xs text-foreground">
                {selectedRequest.agent_run_id.slice(0, 8)}...
              </code>
              {decisionType === 'approve' && ' e continuar seu fluxo de execução.'}
              {decisionType === 'reject' && ' e interromper a execução marcando-a como falha.'}
              {decisionType === 'request-changes' && ' e pausar a execução até novos comandos do usuário.'}
            </p>

            <form onSubmit={handleDecisionSubmit} className="space-y-4">
              <div className="space-y-2">
                <label 
                  htmlFor="decision-reason" 
                  className="block text-xs font-black uppercase text-muted-foreground"
                >
                  Motivo / Justificativa (Opcional)
                </label>
                <textarea
                  id="decision-reason"
                  rows={4}
                  className="w-full px-4 py-3 rounded-xl border border-border bg-background text-foreground text-sm focus:ring-2 focus:ring-primary focus:border-primary outline-none transition-all resize-none"
                  placeholder="Descreva o motivo desta decisão para fins de auditoria..."
                  value={decisionReason}
                  onChange={(e) => setDecisionReason(e.target.value)}
                />
              </div>

              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => {
                    setIsDecisionModalOpen(false)
                    setDecisionReason('')
                  }}
                  className="px-5 py-2.5 rounded-xl border border-border hover:bg-secondary font-bold text-xs transition-all text-muted-foreground"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className={`
                    px-5 py-2.5 rounded-xl text-white font-bold text-xs transition-all shadow-md flex items-center gap-2
                    ${decisionType === 'approve' ? 'bg-emerald-600 hover:bg-emerald-500 border border-emerald-700' : ''}
                    ${decisionType === 'reject' ? 'bg-red-600 hover:bg-red-500 border border-red-700' : ''}
                    ${decisionType === 'request-changes' ? 'bg-blue-600 hover:bg-blue-500 border border-blue-700' : ''}
                    disabled:opacity-50
                  `}
                >
                  {isSubmitting && <RefreshCw className="w-3.5 h-3.5 animate-spin" />}
                  {decisionType === 'approve' ? 'Aprovar Execução' : decisionType === 'reject' ? 'Rejeitar Execução' : 'Enviar Solicitação'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../lib/api'
import { 
  ShieldAlert, 
  ShieldCheck, 
  Clock, 
  XOctagon, 
  AlertTriangle, 
  Check, 
  X, 
  Eye, 
  RefreshCw, 
  ChevronRight, 
  FileText,
  User,
  SlidersHorizontal,
  ChevronDown,
  Activity,
  Terminal,
  Layers
} from 'lucide-react'
import { toast } from 'sonner'

interface CriticalApproval {
  id: string
  action_type: string
  description: string
  status: 'pending' | 'approved' | 'rejected' | 'expired'
  requested_by: string
  requested_at: string
  decided_by?: string
  decided_at?: string
  decision_reason?: string
  expires_at: string
  payload?: any
  metadata_json?: any
}

export default function Approvals() {
  const queryClient = useQueryClient()
  const [selectedRequest, setSelectedRequest] = useState<CriticalApproval | null>(null)
  const [statusFilter, setStatusFilter] = useState<string>('')
  const [isDecisionModalOpen, setIsDecisionModalOpen] = useState(false)
  const [decisionType, setDecisionType] = useState<'approve' | 'reject' | null>(null)
  const [decisionReason, setDecisionReason] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Fetch critical approvals
  const { data: requests = [], isLoading, isRefetching, refetch } = useQuery<CriticalApproval[]>({
    queryKey: ['critical-approvals', statusFilter],
    queryFn: async () => {
      const res = await api.get('/admin/approvals', {
        params: statusFilter ? { status: statusFilter } : {}
      })
      return res.data
    }
  })

  // WebSocket for Real-time updates
  useEffect(() => {
    const wsProto = window.location.protocol === 'https:' ? 'wss:' : 'ws:'
    // Get host, fallback to localhost:8080 if running in dev server on different port without proxy
    let host = window.location.host
    if (host.startsWith('localhost:517')) {
      host = 'localhost:8080'
    }
    const wsUrl = `${wsProto}//${host}/admin/approvals/ws`

    let ws: WebSocket | null = null
    let reconnectTimeout: any = null

    const connect = () => {
      console.log('Connecting to approvals WS:', wsUrl)
      ws = new WebSocket(wsUrl)

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data)
          console.log('Approvals WS Event:', data)

          // Toast notifications based on event type
          if (data.event === 'critical_approval.created') {
            toast.warning(`Nova ação crítica requer aprovação: ${data.action_type.toUpperCase()}`, {
              description: data.description,
              duration: 8000
            })
          } else if (data.event === 'critical_approval.approved') {
            toast.success(`Ação crítica aprovada: ${data.action_type.toUpperCase()}`)
          } else if (data.event === 'critical_approval.rejected') {
            toast.error(`Ação crítica rejeitada: ${data.action_type.toUpperCase()}`)
          } else if (data.event === 'critical_approval.expired') {
            toast.info(`Solicitação de aprovação expirou: ${data.action_type.toUpperCase()}`)
          }

          // Trigger refetch
          queryClient.invalidateQueries({ queryKey: ['critical-approvals'] })

          // Update selected item details if open
          if (selectedRequest && selectedRequest.id === data.id) {
            refetch().then(res => {
              const updated = res.data?.find(r => r.id === data.id)
              if (updated) setSelectedRequest(updated)
            })
          }
        } catch (err) {
          console.error('Failed to parse websocket message:', err)
        }
      }

      ws.onclose = () => {
        console.log('Approvals WS closed. Reconnecting in 3s...')
        reconnectTimeout = setTimeout(connect, 3000)
      }

      ws.onerror = (err) => {
        console.error('Approvals WS error:', err)
        ws?.close()
      }
    }

    connect()

    return () => {
      if (ws) {
        ws.onclose = null // Prevent reconnect loop on unmount
        ws.close()
      }
      if (reconnectTimeout) clearTimeout(reconnectTimeout)
    }
  }, [queryClient, selectedRequest])

  // Mutations for approvals
  const decisionMutation = useMutation({
    mutationFn: async ({ id, type, reason }: { id: string; type: 'approve' | 'reject'; reason: string }) => {
      const endpoint = `/admin/approvals/${id}/${type}`
      const res = await api.post(endpoint, { decision_reason: reason })
      return res.data
    },
    onSuccess: (data) => {
      toast.success(`Solicitação ${data.status === 'approved' ? 'aprovada' : 'rejeitada'} com sucesso!`)
      queryClient.invalidateQueries({ queryKey: ['critical-approvals'] })
      setSelectedRequest(data)
      setIsDecisionModalOpen(false)
      setDecisionReason('')
      setDecisionType(null)
    },
    onError: (err: any) => {
      const detail = err.response?.data?.detail || err.message || 'Erro desconhecido'
      toast.error(`Falha na operação: ${detail}`)
    },
    onSettled: () => {
      setIsSubmitting(false)
    }
  })

  const handleDecisionSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    if (!selectedRequest || !decisionType) return
    setIsSubmitting(true)
    decisionMutation.mutate({
      id: selectedRequest.id,
      type: decisionType,
      reason: decisionReason
    })
  }

  const openDecisionModal = (type: 'approve' | 'reject') => {
    setDecisionType(type)
    setIsDecisionModalOpen(true)
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'approved':
        return <ShieldCheck className="w-5 h-5 text-emerald-500" />
      case 'rejected':
        return <XOctagon className="w-5 h-5 text-rose-500" />
      case 'expired':
        return <Clock className="w-5 h-5 text-gray-500" />
      default:
        return <AlertTriangle className="w-5 h-5 text-amber-500 animate-pulse" />
    }
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case 'approved':
        return 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/20'
      case 'rejected':
        return 'bg-rose-500/10 text-rose-600 dark:text-rose-400 border-rose-500/20'
      case 'expired':
        return 'bg-gray-500/10 text-gray-600 dark:text-gray-400 border-gray-500/20'
      default:
        return 'bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20'
    }
  };

  return (
    <div className="flex flex-col gap-6 h-[calc(100vh-7rem)] overflow-hidden">
      {/* Top Header */}
      <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 border-b border-border pb-5">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-foreground flex items-center gap-2">
            <ShieldAlert className="w-6 h-6 text-amber-500" />
            Human Approval Center
          </h1>
          <p className="text-muted-foreground text-sm mt-1">
            Gerencie e conceda permissão de segurança para ações críticas e sensíveis do sistema.
          </p>
        </div>
        <button
          onClick={() => refetch()}
          disabled={isLoading || isRefetching}
          className="flex items-center gap-2 px-4 py-2 text-sm font-medium bg-secondary hover:bg-secondary/80 rounded-xl border border-border transition-colors disabled:opacity-50"
        >
          <RefreshCw className={`w-4 h-4 ${(isLoading || isRefetching) ? 'animate-spin' : ''}`} />
          Atualizar
        </button>
      </header>

      {/* Main Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 overflow-hidden">
        {/* Left Side: Requests List */}
        <section className="lg:col-span-5 flex flex-col bg-card rounded-2xl border border-border overflow-hidden">
          <div className="p-4 border-b border-border flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-secondary/20">
            <h2 className="font-semibold text-sm text-foreground flex items-center gap-2">
              <Activity className="w-4 h-4 text-primary" />
              Solicitações ({requests.length})
            </h2>
            <div className="flex items-center gap-2">
              <SlidersHorizontal className="w-3.5 h-3.5 text-muted-foreground" />
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="text-xs bg-background border border-border rounded-lg px-2 py-1 text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
              >
                <option value="">Status: Todos</option>
                <option value="pending">Pendente</option>
                <option value="approved">Aprovado</option>
                <option value="rejected">Rejeitado</option>
                <option value="expired">Expirado</option>
              </select>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto divide-y divide-border">
            {isLoading ? (
              <div className="flex flex-col items-center justify-center p-12 text-muted-foreground gap-3">
                <RefreshCw className="w-8 h-8 animate-spin text-primary" />
                <span className="text-sm">Carregando solicitações...</span>
              </div>
            ) : requests.length === 0 ? (
              <div className="flex flex-col items-center justify-center p-12 text-muted-foreground text-center gap-2">
                <ShieldCheck className="w-10 h-10 text-emerald-500/50" />
                <span className="text-sm font-semibold">Tudo Limpo!</span>
                <span className="text-xs">Nenhuma solicitação de aprovação pendente encontrada.</span>
              </div>
            ) : (
              requests.map((req) => (
                <div
                  key={req.id}
                  onClick={() => setSelectedRequest(req)}
                  className={`p-4 flex items-start justify-between gap-3 cursor-pointer hover:bg-secondary/25 transition-all ${
                    selectedRequest?.id === req.id ? 'bg-secondary/40 border-l-2 border-primary' : ''
                  }`}
                >
                  <div className="flex flex-col gap-1.5 min-w-0">
                    <span className="font-mono text-[10px] text-muted-foreground truncate">{req.id}</span>
                    <span className="font-semibold text-sm text-foreground truncate uppercase">{req.action_type}</span>
                    <p className="text-xs text-muted-foreground line-clamp-1">{req.description}</p>
                    <div className="flex items-center gap-2 mt-1">
                      <span className="text-[10px] text-muted-foreground flex items-center gap-1">
                        <User className="w-3 h-3" /> {req.requested_by}
                      </span>
                    </div>
                  </div>
                  <div className="flex flex-col items-end gap-2 shrink-0">
                    <span className={`text-[10px] px-2 py-0.5 rounded-full border font-medium uppercase ${getStatusStyle(req.status)}`}>
                      {req.status}
                    </span>
                    <ChevronRight className="w-4 h-4 text-muted-foreground" />
                  </div>
                </div>
              ))
            )}
          </div>
        </section>

        {/* Right Side: Details / Action panel */}
        <section className="lg:col-span-7 flex flex-col bg-card rounded-2xl border border-border overflow-hidden">
          {selectedRequest ? (
            <div className="flex flex-col h-full overflow-hidden">
              {/* Request Header Details */}
              <div className="p-5 border-b border-border flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-secondary/10">
                <div className="min-w-0">
                  <span className="font-mono text-xs text-muted-foreground">{selectedRequest.id}</span>
                  <h3 className="text-lg font-bold text-foreground uppercase mt-1 flex items-center gap-2">
                    {getStatusIcon(selectedRequest.status)}
                    {selectedRequest.action_type}
                  </h3>
                </div>
                <div className="flex items-center gap-2">
                  <span className={`text-xs px-2.5 py-1 rounded-full border font-bold uppercase ${getStatusStyle(selectedRequest.status)}`}>
                    {selectedRequest.status}
                  </span>
                </div>
              </div>

              {/* Scrollable details contents */}
              <div className="flex-1 overflow-y-auto p-6 space-y-6">
                {/* Description Box */}
                <div className="bg-secondary/20 p-4 rounded-xl border border-border space-y-2">
                  <h4 className="text-xs font-semibold text-muted-foreground uppercase flex items-center gap-1.5">
                    <FileText className="w-3.5 h-3.5 text-primary" /> Descrição da Ação
                  </h4>
                  <p className="text-sm text-foreground">{selectedRequest.description}</p>
                </div>

                {/* Properties list */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="border border-border p-3.5 rounded-xl bg-background flex flex-col gap-1">
                    <span className="text-[10px] font-semibold text-muted-foreground uppercase">Solicitado por</span>
                    <span className="text-sm font-medium text-foreground">{selectedRequest.requested_by}</span>
                  </div>
                  <div className="border border-border p-3.5 rounded-xl bg-background flex flex-col gap-1">
                    <span className="text-[10px] font-semibold text-muted-foreground uppercase">Data da Solicitação</span>
                    <span className="text-sm font-medium text-foreground">
                      {new Date(selectedRequest.requested_at).toLocaleString()}
                    </span>
                  </div>
                  {selectedRequest.expires_at && (
                    <div className="border border-border p-3.5 rounded-xl bg-background flex flex-col gap-1">
                      <span className="text-[10px] font-semibold text-muted-foreground uppercase">Expira em</span>
                      <span className="text-sm font-medium text-rose-500 flex items-center gap-1">
                        <Clock className="w-4 h-4" />
                        {new Date(selectedRequest.expires_at).toLocaleString()}
                      </span>
                    </div>
                  )}
                  {selectedRequest.decided_by && (
                    <div className="border border-border p-3.5 rounded-xl bg-background flex flex-col gap-1">
                      <span className="text-[10px] font-semibold text-muted-foreground uppercase">Decidido por</span>
                      <span className="text-sm font-medium text-foreground">
                        {selectedRequest.decided_by} em {selectedRequest.decided_at ? new Date(selectedRequest.decided_at).toLocaleString() : ''}
                      </span>
                    </div>
                  )}
                </div>

                {/* Decision Reason (if exists) */}
                {selectedRequest.decision_reason && (
                  <div className="bg-secondary/15 p-4 rounded-xl border border-border space-y-1.5">
                    <h4 className="text-xs font-semibold text-muted-foreground uppercase">Justificativa da Decisão</h4>
                    <p className="text-sm text-foreground">{selectedRequest.decision_reason}</p>
                  </div>
                )}

                {/* Payload details */}
                {selectedRequest.payload && (
                  <div className="space-y-2">
                    <h4 className="text-xs font-semibold text-muted-foreground uppercase flex items-center gap-1.5">
                      <Terminal className="w-3.5 h-3.5 text-primary" /> Parâmetros / Payload
                    </h4>
                    <pre className="text-xs bg-zinc-950 text-zinc-100 p-4 rounded-xl overflow-x-auto border border-zinc-800 font-mono shadow-inner">
                      {JSON.stringify(selectedRequest.payload, null, 2)}
                    </pre>
                  </div>
                )}

                {/* Metadata details */}
                {selectedRequest.metadata_json && (
                  <div className="space-y-2">
                    <h4 className="text-xs font-semibold text-muted-foreground uppercase flex items-center gap-1.5">
                      <Layers className="w-3.5 h-3.5 text-primary" /> Metadados da Ação
                    </h4>
                    <pre className="text-xs bg-zinc-950 text-zinc-100 p-4 rounded-xl overflow-x-auto border border-zinc-800 font-mono shadow-inner">
                      {JSON.stringify(selectedRequest.metadata_json, null, 2)}
                    </pre>
                  </div>
                )}
              </div>

              {/* Action buttons (only for pending) */}
              {selectedRequest.status === 'pending' && (
                <div className="p-4 border-t border-border flex justify-end gap-3 bg-secondary/10">
                  <button
                    onClick={() => openDecisionModal('reject')}
                    className="flex items-center gap-2 px-5 py-2.5 text-sm font-semibold bg-rose-600 hover:bg-rose-700 text-white rounded-xl shadow-md hover:shadow-lg transition-all"
                  >
                    <X className="w-4 h-4" /> Rejeitar Ação
                  </button>
                  <button
                    onClick={() => openDecisionModal('approve')}
                    className="flex items-center gap-2 px-5 py-2.5 text-sm font-semibold bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl shadow-md hover:shadow-lg transition-all"
                  >
                    <Check className="w-4 h-4" /> Autorizar Ação
                  </button>
                </div>
              )}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full text-muted-foreground text-center p-8 gap-4 bg-secondary/5">
              <ShieldAlert className="w-16 h-16 text-muted-foreground/30" />
              <div>
                <h3 className="font-semibold text-lg">Nenhum Item Selecionado</h3>
                <p className="text-sm max-w-sm mt-1">
                  Selecione uma solicitação de aprovação na lista lateral para visualizar os detalhes e tomar decisões.
                </p>
              </div>
            </div>
          )}
        </section>
      </div>

      {/* Decision Modal */}
      {isDecisionModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="w-full max-w-md bg-card border border-border rounded-2xl shadow-xl overflow-hidden animate-in fade-in duration-200">
            <div className="p-5 border-b border-border flex items-center justify-between">
              <h3 className="font-bold text-foreground">
                {decisionType === 'approve' ? 'Autorizar Ação Crítica' : 'Rejeitar Ação Crítica'}
              </h3>
              <button
                onClick={() => setIsDecisionModalOpen(false)}
                className="p-1 hover:bg-secondary rounded-lg text-muted-foreground hover:text-foreground transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>
            <form onSubmit={handleDecisionSubmit}>
              <div className="p-5 space-y-4">
                <p className="text-sm text-muted-foreground">
                  Por favor, forneça uma justificativa para esta decisão. A justificativa será registrada no log de auditoria permanente.
                </p>
                <div className="space-y-2">
                  <label htmlFor="reason-input" className="text-xs font-semibold text-foreground uppercase">Justificativa</label>
                  <textarea
                    id="reason-input"
                    required
                    rows={4}
                    placeholder="Digite a justificativa de segurança..."
                    className="w-full px-3 py-2 text-sm text-foreground bg-background border border-border rounded-xl focus:ring-2 focus:ring-primary focus:border-primary outline-none transition-all resize-none"
                    value={decisionReason}
                    onChange={(e) => setDecisionReason(e.target.value)}
                  />
                </div>
              </div>
              <div className="p-4 border-t border-border bg-secondary/15 flex justify-end gap-3">
                <button
                  type="button"
                  onClick={() => setIsDecisionModalOpen(false)}
                  className="px-4 py-2 text-sm font-semibold hover:bg-secondary rounded-xl transition-colors border border-border text-foreground"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting}
                  className={`px-5 py-2 rounded-xl text-sm font-bold text-white shadow-md hover:shadow-lg transition-all ${
                    decisionType === 'approve' 
                      ? 'bg-emerald-600 hover:bg-emerald-700' 
                      : 'bg-rose-600 hover:bg-rose-700'
                  }`}
                >
                  {isSubmitting ? 'Processando...' : decisionType === 'approve' ? 'Autorizar' : 'Rejeitar'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  )
}

import { useMemo, useState, type ReactNode } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Activity,
  AlertCircle,
  CheckCircle2,
  Cpu,
  Play,
  Plus,
  RefreshCw,
  RotateCcw,
  Server,
  Square,
  Terminal,
} from 'lucide-react'
import { toast } from 'sonner'
import type { ColumnDef } from '@tanstack/react-table'

import { AdvancedTable } from '../components/table/advanced-table'
import api from '../lib/api'

type Backend = {
  id: string
  name: string
  provider: string
  backend_url: string
  healthcheck_path: string
  is_active: boolean
  is_default: boolean
  status: string
  max_parallel_requests: number
  current_running: number
  metadata_json?: string | null
  health?: {
    ok?: boolean
    status?: string
    detail?: string
  } | null
}

type BackendForm = {
  name: string
  provider: string
  backend_url: string
  healthcheck_path: string
  is_active: boolean
  is_default: boolean
  status: string
  max_parallel_requests: number
  metadata_json: string
}

const EMPTY_FORM: BackendForm = {
  name: '',
  provider: 'llama.cpp',
  backend_url: '',
  healthcheck_path: '/health',
  is_active: true,
  is_default: false,
  status: 'configured',
  max_parallel_requests: 8,
  metadata_json: '',
}

export default function Backends() {
  const queryClient = useQueryClient()
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })
  const [filters, setFilters] = useState<any>({})
  const [sorting, setSorting] = useState<any[]>([])
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [selectedBackend, setSelectedBackend] = useState<Backend | null>(null)
  const [backendForm, setBackendForm] = useState<BackendForm>(EMPTY_FORM)
  const [testedModels, setTestedModels] = useState<any[] | null>(null)

  const { data: backendsData, isLoading } = useQuery<{ items: Backend[]; total: number }>({
    queryKey: ['backends', pagination, filters, sorting],
    queryFn: async () => {
      const res = await api.get('/admin/backends', {
        params: {
          page: pagination.pageIndex + 1,
          limit: pagination.pageSize,
          ...filters,
        },
      })
      const payload = res.data
      if (Array.isArray(payload)) return { items: payload, total: payload.length }
      return {
        items: Array.isArray(payload?.items) ? payload.items : [],
        total: typeof payload?.total === 'number' ? payload.total : 0,
      }
    },
  })

  const backends = backendsData?.items || []
  const selected = selectedBackend || backends[0] || null

  const { data: selectedHealth } = useQuery({
    queryKey: ['backend-health', selected?.id],
    queryFn: async () => {
      if (!selected?.id) return null
      return api.getBackendHealth(selected.id)
    },
    enabled: !!selected?.id,
  })

  const { data: selectedLogs } = useQuery({
    queryKey: ['backend-logs', selected?.id],
    queryFn: async () => {
      if (!selected?.id) return null
      return api.getBackendLogs(selected.id)
    },
    enabled: !!selected?.id,
  })

  const actionMutation = useMutation({
    mutationFn: async ({ id, action }: { id: string; action: 'start' | 'stop' | 'restart' | 'reconcile' }) => {
      if (action === 'start') return api.startBackend(id)
      if (action === 'stop') return api.stopBackend(id)
      if (action === 'restart') return api.restartBackend(id)
      return api.reconcileBackend(id)
    },
    onSuccess: (_, variables) => {
      toast.success(`Ação ${variables.action} executada.`)
      queryClient.invalidateQueries({ queryKey: ['backends'] })
      queryClient.invalidateQueries({ queryKey: ['backend-health', variables.id] })
      queryClient.invalidateQueries({ queryKey: ['backend-logs', variables.id] })
    },
    onError: (error: any) => {
      toast.error(error?.message || 'Falha na operação do backend')
    },
  })

  const createMutation = useMutation({
    mutationFn: async () => {
      const payload = {
        name: backendForm.name.trim(),
        provider: backendForm.provider,
        backend_url: backendForm.backend_url.trim(),
        healthcheck_path: backendForm.healthcheck_path.trim() || '/health',
        is_active: backendForm.is_active,
        is_default: backendForm.is_default,
        status: backendForm.status.trim() || 'configured',
        max_parallel_requests: Number(backendForm.max_parallel_requests) || 8,
        metadata_json: backendForm.metadata_json.trim() || null,
      }
      return api.createBackend(payload)
    },
    onSuccess: () => {
      toast.success('Backend criado com sucesso.')
      setIsCreateOpen(false)
      setBackendForm(EMPTY_FORM)
      queryClient.invalidateQueries({ queryKey: ['backends'] })
    },
    onError: (error: any) => {
      toast.error(error?.message || 'Falha ao criar backend')
    },
  })

  const testConnectionMutation = useMutation({
    mutationFn: async () => {
      const payload = {
        name: backendForm.name.trim() || 'preview-backend',
        provider: backendForm.provider,
        backend_url: backendForm.backend_url.trim(),
        healthcheck_path: backendForm.healthcheck_path.trim() || '/health',
        is_active: backendForm.is_active,
        is_default: backendForm.is_default,
        status: backendForm.status.trim() || 'configured',
        max_parallel_requests: Number(backendForm.max_parallel_requests) || 8,
        metadata_json: backendForm.metadata_json.trim() || null,
      }
      return api.testConnection(payload)
    },
    onSuccess: (result: any) => {
      toast.success(result?.ok ? 'Conexao validada com sucesso.' : 'Backend respondeu sem health OK.')
    },
    onError: (error: any) => {
      toast.error(error?.message || 'Falha ao testar conexao')
    },
  })

  const listModelsMutation = useMutation({
    mutationFn: async () => {
      if (!selected) throw new Error('Selecione um backend primeiro.')
      return api.listBackendModels({
        name: selected.name,
        provider: selected.provider,
        backend_url: selected.backend_url,
        healthcheck_path: selected.healthcheck_path,
        is_active: selected.is_active,
        is_default: selected.is_default,
        status: selected.status,
        max_parallel_requests: selected.max_parallel_requests,
        metadata_json: selected.metadata_json || null,
      })
    },
    onSuccess: (result: any) => {
      setTestedModels(Array.isArray(result) ? result : result?.data || result?.models || [])
      toast.success('Modelos remotos carregados.')
    },
    onError: (error: any) => {
      toast.error(error?.message || 'Falha ao listar modelos do backend')
    },
  })

  const activeCount = backends.filter(item => item.is_active).length
  const providersCount = new Set(backends.map(item => item.provider)).size
  const totalRunning = backends.reduce((acc, item) => acc + (item.current_running || 0), 0)

  const columns = useMemo<ColumnDef<Backend>[]>(() => [
    {
      accessorKey: 'name',
      header: 'Backend',
      cell: ({ row }) => (
        <button
          type="button"
          onClick={() => setSelectedBackend(row.original)}
          className="flex w-full items-center gap-3 text-left"
        >
          <div className={`rounded-lg p-2 ${row.original.is_active ? 'bg-primary/10 text-primary' : 'bg-secondary text-muted-foreground'}`}>
            <Cpu className="h-4 w-4" />
          </div>
          <div>
            <div className="font-bold text-foreground">{row.original.name}</div>
            <div className="text-[10px] font-mono text-muted-foreground">{row.original.id}</div>
          </div>
        </button>
      ),
    },
    {
      accessorKey: 'backend_url',
      header: 'Endpoint',
      cell: ({ row }) => (
        <div className="max-w-[260px] truncate text-[10px] font-mono text-muted-foreground">
          {row.original.backend_url}
        </div>
      ),
    },
    {
      accessorKey: 'provider',
      header: 'Provider',
      cell: ({ row }) => (
        <span className="rounded-md bg-secondary px-2 py-0.5 text-[10px] font-black uppercase text-muted-foreground">
          {row.original.provider}
        </span>
      ),
    },
    {
      accessorKey: 'status',
      header: 'Estado',
      cell: ({ row }) => {
        const ok = row.original.health?.ok ?? row.original.is_active
        return ok ? (
          <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase text-emerald-600">
            <CheckCircle2 className="h-3.5 w-3.5" /> {row.original.status || 'healthy'}
          </span>
        ) : (
          <span className="inline-flex items-center gap-1 text-[10px] font-black uppercase text-destructive">
            <AlertCircle className="h-3.5 w-3.5" /> {row.original.status || 'offline'}
          </span>
        )
      },
    },
    {
      accessorKey: 'max_parallel_requests',
      header: 'Capacidade',
      cell: ({ row }) => (
        <div className="text-xs text-foreground">
          <div>{row.original.current_running || 0} em execucao</div>
          <div className="text-[10px] text-muted-foreground">max {row.original.max_parallel_requests || 0}</div>
        </div>
      ),
    },
    {
      id: 'actions',
      header: 'Acoes',
      cell: ({ row }) => (
        <div className="flex justify-end gap-2">
          <button
            type="button"
            onClick={() => actionMutation.mutate({ id: row.original.id, action: row.original.is_active ? 'stop' : 'start' })}
            className="rounded-lg p-2 text-muted-foreground transition-all hover:bg-secondary"
          >
            {row.original.is_active ? <Square className="h-4 w-4" /> : <Play className="h-4 w-4 text-primary" />}
          </button>
          <button
            type="button"
            onClick={() => actionMutation.mutate({ id: row.original.id, action: 'restart' })}
            className="rounded-lg p-2 text-muted-foreground transition-all hover:bg-secondary"
          >
            <RotateCcw className="h-4 w-4" />
          </button>
        </div>
      ),
      enableHiding: false,
    },
  ], [actionMutation])

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-foreground">Backends</h1>
          <p className="text-sm md:text-lg text-muted-foreground">Controle operacional de providers, health, logs e lifecycle.</p>
        </div>
        <div className="flex flex-col gap-3 sm:flex-row">
          <button
            type="button"
            onClick={() => queryClient.invalidateQueries({ queryKey: ['backends'] })}
            className="rounded-xl border border-border px-4 py-2.5 text-sm font-bold text-foreground hover:bg-secondary"
          >
            Atualizar
          </button>
          <button
            type="button"
            onClick={() => setIsCreateOpen(true)}
            className="flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-primary/20 hover:bg-primary/90"
          >
