import { useEffect, useMemo, useState, type ReactNode } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import api from '../lib/api'
import { Building2, LayoutGrid, ShieldCheck, Plus, Copy, RefreshCw, Power, Server, AlertCircle } from 'lucide-react'

type Organization = {
  id: string
  name: string
  slug: string
  status: string
  created_at: string
}

type Workspace = {
  id: string
  organization_id: string
  name: string
  slug: string
  created_at: string
}

type Appliance = {
  id: string
  workspace_id: string
  appliance_external_id: string
  name: string
  status: string
  version?: string | null
  health_status?: string | null
  readiness: boolean
  last_heartbeat_at?: string | null
  created_at: string
}

function StatCard({ label, value, hint, icon }: { label: string; value: string; hint: string; icon: ReactNode }) {
  return (
    <div className="rounded-3xl border border-border bg-card p-5 shadow-sm">
      <div className="flex items-center justify-between gap-4">
        <div>
          <p className="text-xs font-black uppercase tracking-[0.2em] text-muted-foreground">{label}</p>
          <p className="mt-2 text-3xl font-black text-foreground">{value}</p>
          <p className="mt-1 text-sm text-muted-foreground">{hint}</p>
        </div>
        <div className="rounded-2xl bg-primary/10 p-3 text-primary">{icon}</div>
      </div>
    </div>
  )
}

export default function ManagedControlPlane() {
  const queryClient = useQueryClient()
  const [orgName, setOrgName] = useState('')
  const [orgSlug, setOrgSlug] = useState('')
  const [workspaceName, setWorkspaceName] = useState('')
  const [workspaceSlug, setWorkspaceSlug] = useState('')
  const [workspaceOrgId, setWorkspaceOrgId] = useState('')
  const [tokenWorkspaceId, setTokenWorkspaceId] = useState('')
  const [enrollmentToken, setEnrollmentToken] = useState<string | null>(null)
  const [enrollmentExpiresAt, setEnrollmentExpiresAt] = useState<string | null>(null)

  const { data: organizations = [], isLoading: orgsLoading } = useQuery({
    queryKey: ['managed-organizations'],
    queryFn: async () => (await api.get('/managed/organizations')).data as Organization[],
  })

  const { data: workspaces = [], isLoading: workspacesLoading } = useQuery({
    queryKey: ['managed-workspaces'],
    queryFn: async () => (await api.get('/managed/workspaces')).data as Workspace[],
  })

  const { data: appliances = [], isLoading: appliancesLoading } = useQuery({
    queryKey: ['managed-appliances'],
    queryFn: async () => (await api.get('/managed/appliances')).data as Appliance[],
  })

  useEffect(() => {
    if (!workspaceOrgId && organizations.length > 0) {
      setWorkspaceOrgId(organizations[0].id)
    }
    if (!tokenWorkspaceId && workspaces.length > 0) {
      setTokenWorkspaceId(workspaces[0].id)
    }
  }, [organizations, workspaces, workspaceOrgId, tokenWorkspaceId])

  const createOrganization = useMutation({
    mutationFn: async () => {
      const res = await api.post('/managed/organizations', {
        name: orgName.trim(),
        slug: orgSlug.trim(),
      })
      return res.data as Organization
    },
    onSuccess: () => {
      setOrgName('')
      setOrgSlug('')
      queryClient.invalidateQueries({ queryKey: ['managed-organizations'] })
      queryClient.invalidateQueries({ queryKey: ['managed-workspaces'] })
    },
  })

  const createWorkspace = useMutation({
    mutationFn: async () => {
      const res = await api.post('/managed/workspaces', {
        organization_id: workspaceOrgId,
        name: workspaceName.trim(),
        slug: workspaceSlug.trim(),
      })
      return res.data as Workspace
    },
    onSuccess: () => {
      setWorkspaceName('')
      setWorkspaceSlug('')
      queryClient.invalidateQueries({ queryKey: ['managed-workspaces'] })
    },
  })

  const createEnrollmentToken = useMutation({
    mutationFn: async () => {
      const res = await api.post('/managed/appliances/enrollment-token', null, {
        params: {
          workspace_id: tokenWorkspaceId,
          expires_in_hours: 24,
        },
      })
      return res.data as { enrollment_token: string; expires_at: string }
    },
    onSuccess: data => {
      setEnrollmentToken(data.enrollment_token)
      setEnrollmentExpiresAt(data.expires_at)
    },
  })

  const revokeAppliance = useMutation({
    mutationFn: async (applianceId: string) => api.post(`/managed/appliances/${applianceId}/revoke`),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['managed-appliances'] })
    },
  })

  const selectedWorkspaces = useMemo(
    () => workspaces.filter(workspace => !workspaceOrgId || workspace.organization_id === workspaceOrgId),
    [workspaces, workspaceOrgId],
  )

  const stats = useMemo(() => {
    const online = appliances.filter(appliance => appliance.status === 'online').length
    const revoked = appliances.filter(appliance => appliance.status === 'revoked').length
    return {
      orgs: organizations.length,
      workspaces: workspaces.length,
      appliances: appliances.length,
      online,
      revoked,
    }
  }, [organizations.length, workspaces.length, appliances])

  const isLoading = orgsLoading || workspacesLoading || appliancesLoading
  const formDisabled = !orgName.trim() || !orgSlug.trim() || createOrganization.isPending
  const workspaceDisabled = !workspaceOrgId || !workspaceName.trim() || !workspaceSlug.trim() || createWorkspace.isPending
  const tokenDisabled = !tokenWorkspaceId || createEnrollmentToken.isPending

  return (
    <div className="mx-auto max-w-7xl px-4 py-8">
      <header className="mb-8">
        <div className="inline-flex items-center gap-2 rounded-full border border-border bg-secondary px-3 py-1 text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">
          <ShieldCheck className="h-3.5 w-3.5" />
          SaaS / Managed Control Plane
        </div>
        <h1 className="mt-4 text-4xl font-black tracking-tight text-foreground">
          Managed <span className="text-primary">Control Plane</span>
        </h1>
        <p className="mt-2 max-w-3xl text-muted-foreground">
          Esta tela agora reflete o backend real: organizações, workspaces, appliances e enrollment tokens.
          Não há, hoje, endpoints próprios para billing/support/link sync neste módulo.
        </p>
      </header>

      <div className="mb-8 grid gap-4 md:grid-cols-2 xl:grid-cols-5">
        <StatCard label="Organizations" value={String(stats.orgs)} hint="Registradas no backend" icon={<Building2 className="h-5 w-5" />} />
        <StatCard label="Workspaces" value={String(stats.workspaces)} hint="Vinculados a organizações" icon={<LayoutGrid className="h-5 w-5" />} />
        <StatCard label="Appliances" value={String(stats.appliances)} hint="Enrolled ou ativos" icon={<Server className="h-5 w-5" />} />
        <StatCard label="Online" value={String(stats.online)} hint="Com heartbeat recente" icon={<RefreshCw className="h-5 w-5" />} />
        <StatCard label="Revoked" value={String(stats.revoked)} hint="Bloqueados no backend" icon={<Power className="h-5 w-5" />} />
      </div>

      <div className="grid gap-6 xl:grid-cols-3">
        <section className="rounded-3xl border border-border bg-card p-6 shadow-sm xl:col-span-1">
          <div className="mb-5 flex items-center gap-2">
            <Plus className="h-5 w-5 text-primary" />
            <h2 className="text-lg font-black text-foreground">Criar Organização</h2>
          </div>
          <div className="space-y-3">
            <input
              value={orgName}
              onChange={e => setOrgName(e.target.value)}
              placeholder="Nome da organização"
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            />
            <input
              value={orgSlug}
              onChange={e => setOrgSlug(e.target.value)}
              placeholder="slug"
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            />
            <button
              onClick={() => createOrganization.mutate()}
              disabled={formDisabled}
              className="w-full rounded-2xl bg-foreground px-4 py-3 text-sm font-bold text-background transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {createOrganization.isPending ? 'Criando...' : 'Criar Organização'}
            </button>
          </div>

          <div className="mt-8 border-t border-border pt-6">
            <h3 className="mb-3 text-sm font-black uppercase tracking-[0.2em] text-muted-foreground">Organizações</h3>
            <div className="space-y-2">
              {isLoading && <div className="text-sm text-muted-foreground">Carregando...</div>}
              {!isLoading && organizations.length === 0 && (
                <div className="rounded-2xl border border-dashed border-border bg-secondary/50 p-4 text-sm text-muted-foreground">
                  Nenhuma organização cadastrada.
                </div>
              )}
              {organizations.map(org => (
                <div key={org.id} className="rounded-2xl border border-border bg-secondary/40 p-4">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <div className="font-bold text-foreground">{org.name}</div>
                      <div className="text-xs text-muted-foreground">{org.slug}</div>
                    </div>
                    <span className="rounded-full bg-primary/10 px-2 py-1 text-[10px] font-black uppercase tracking-[0.2em] text-primary">
                      {org.status}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </section>

        <section className="rounded-3xl border border-border bg-card p-6 shadow-sm xl:col-span-1">
          <div className="mb-5 flex items-center gap-2">
            <Plus className="h-5 w-5 text-primary" />
            <h2 className="text-lg font-black text-foreground">Criar Workspace</h2>
          </div>
          <div className="space-y-3">
            <select
              value={workspaceOrgId}
              onChange={e => setWorkspaceOrgId(e.target.value)}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            >
              <option value="">Selecione a organização</option>
              {organizations.map(org => (
                <option key={org.id} value={org.id}>
                  {org.name}
                </option>
              ))}
            </select>
            <input
              value={workspaceName}
              onChange={e => setWorkspaceName(e.target.value)}
              placeholder="Nome do workspace"
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            />
            <input
              value={workspaceSlug}
              onChange={e => setWorkspaceSlug(e.target.value)}
              placeholder="slug"
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            />
            <button
              onClick={() => createWorkspace.mutate()}
              disabled={workspaceDisabled}
              className="w-full rounded-2xl bg-foreground px-4 py-3 text-sm font-bold text-background transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {createWorkspace.isPending ? 'Criando...' : 'Criar Workspace'}
            </button>
          </div>

          <div className="mt-8 border-t border-border pt-6">
            <h3 className="mb-3 text-sm font-black uppercase tracking-[0.2em] text-muted-foreground">Workspaces</h3>
            <div className="space-y-2">
              {workspaces.length === 0 && !isLoading && (
                <div className="rounded-2xl border border-dashed border-border bg-secondary/50 p-4 text-sm text-muted-foreground">
                  Nenhum workspace cadastrado.
                </div>
              )}
              {selectedWorkspaces.map(workspace => {
                const org = organizations.find(item => item.id === workspace.organization_id)
                return (
                  <div key={workspace.id} className="rounded-2xl border border-border bg-secondary/40 p-4">
                    <div className="font-bold text-foreground">{workspace.name}</div>
                    <div className="text-xs text-muted-foreground">
                      {workspace.slug} · {org?.name || workspace.organization_id}
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </section>

        <section className="rounded-3xl border border-border bg-card p-6 shadow-sm xl:col-span-1">
          <div className="mb-5 flex items-center gap-2">
            <AlertCircle className="h-5 w-5 text-primary" />
            <h2 className="text-lg font-black text-foreground">Appliances</h2>
          </div>

          <div className="space-y-3">
            <select
              value={tokenWorkspaceId}
              onChange={e => setTokenWorkspaceId(e.target.value)}
              className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
            >
              <option value="">Selecione o workspace</option>
              {workspaces.map(workspace => (
                <option key={workspace.id} value={workspace.id}>
                  {workspace.name}
                </option>
              ))}
            </select>
            <button
              onClick={() => createEnrollmentToken.mutate()}
              disabled={tokenDisabled}
              className="w-full rounded-2xl bg-primary px-4 py-3 text-sm font-bold text-white transition-opacity hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {createEnrollmentToken.isPending ? 'Gerando...' : 'Gerar Enrollment Token'}
            </button>
            {enrollmentToken && (
              <div className="rounded-2xl border border-border bg-secondary/50 p-4">
                <div className="flex items-center justify-between gap-3">
                  <div>
                    <p className="text-[10px] font-black uppercase tracking-[0.2em] text-muted-foreground">Token</p>
                    <p className="mt-1 break-all font-mono text-xs text-foreground">{enrollmentToken}</p>
                    {enrollmentExpiresAt && <p className="mt-2 text-xs text-muted-foreground">Expira em {new Date(enrollmentExpiresAt).toLocaleString()}</p>}
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => createEnrollmentToken.mutate()}
                      className="rounded-xl border border-border bg-background px-3 py-2 text-xs font-bold text-muted-foreground transition-colors hover:text-foreground hover:bg-secondary"
                      title="Rotacionar token"
                      disabled={createEnrollmentToken.isPending || !tokenWorkspaceId}
                    >
                      {createEnrollmentToken.isPending ? 'Rotacionando...' : 'Rotacionar'}
                    </button>
                    <button
                      onClick={() => navigator.clipboard.writeText(enrollmentToken)}
                      className="rounded-xl border border-border bg-background p-2 text-muted-foreground transition-colors hover:text-foreground"
                      title="Copiar token"
                    >
                      <Copy className="h-4 w-4" />
                    </button>
                  </div>
                </div>
              </div>
            )}
          </div>

          <div className="mt-8 border-t border-border pt-6">
            <h3 className="mb-3 text-sm font-black uppercase tracking-[0.2em] text-muted-foreground">Appliances registrados</h3>
            <div className="space-y-3">
              {appliances.length === 0 && !isLoading && (
                <div className="rounded-2xl border border-dashed border-border bg-secondary/50 p-4 text-sm text-muted-foreground">
                  Nenhum appliance enrolled.
                </div>
              )}
              {appliances.map(appliance => {
                const workspace = workspaces.find(item => item.id === appliance.workspace_id)
                const healthLabel = appliance.health_status || 'unknown'
                return (
                  <div key={appliance.id} className="rounded-2xl border border-border bg-secondary/40 p-4">
                    <div className="flex items-start justify-between gap-4">
                      <div>
                        <div className="font-bold text-foreground">{appliance.name}</div>
                        <div className="text-xs text-muted-foreground">{workspace?.name || appliance.workspace_id}</div>
                        <div className="mt-1 text-xs text-muted-foreground">
                          {appliance.version || 'sem versão'} · {appliance.readiness ? 'ready' : 'not ready'}
                        </div>
                      </div>
                      <span className="rounded-full bg-primary/10 px-2 py-1 text-[10px] font-black uppercase tracking-[0.2em] text-primary">
                        {healthLabel}
                      </span>
                    </div>
                    <div className="mt-4 flex items-center justify-between gap-3">
                      <span className="text-xs font-medium text-muted-foreground">{appliance.status}</span>
                      <button
                        onClick={() => revokeAppliance.mutate(appliance.id)}
                        className="inline-flex items-center gap-2 rounded-xl bg-destructive px-3 py-2 text-xs font-bold text-white transition-opacity hover:opacity-90 disabled:opacity-50"
                        disabled={revokeAppliance.isPending}
                      >
                        <Power className="h-3.5 w-3.5" />
                        Revoke
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        </section>
      </div>
    </div>
  )
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../lib/api'
import { Plus, Box, CheckCircle2, XCircle, Settings2, Database, RefreshCw, Zap, Power, PowerOff, Trash2 } from 'lucide-react'
import { useState } from 'react'
import { AdvancedTable } from '../components/table/advanced-table'
import { toast } from 'sonner'
import type { ColumnDef } from '@tanstack/react-table'

interface Model {
  id: string
  display_name: string
  model_id: string
  provider: string
  is_active: boolean
  is_default: boolean
  context_length: number
  pricing_unit: string
  input_price: number
  output_price: number
  inference_backend_id: string
  model_file: string
}

interface ModelRuntimeInstance {
  id: string
  model_id: string
  backend_id: string
  model_path: string
  port: number
  status: 'loading' | 'ready' | 'failed' | 'unloading' | 'stopped'
  is_active: boolean
  health_status: string
  last_error: string | null
}

interface BackendOption {
  id: string
  name: string
  provider: string
  backend_url: string
  is_active: boolean
}

interface ModelsResponse {
  registry?: Model[]
  items?: Model[]
  total?: number
  backends?: BackendOption[]
}

export default function Models() {
  const [pagination, setPagination] = useState({ pageIndex: 0, pageSize: 10 })
  const [filters, setFilters] = useState<any>({})
  const [sorting, setSorting] = useState<any[]>([])
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [createForm, setCreateForm] = useState({
    display_name: '',
    model_id: '',
    model_alias: '',
    inference_backend_id: '',
    provider: 'llama.cpp',
    model_file: '',
    context_length: 4096,
    is_active: true,
    is_default: false,
    status: 'configured',
    allow_reasoning: true,
    include_reasoning_default: false,
    prompt_template: '',
  })
  const queryClient = useQueryClient()

  const { data: modelsData, isLoading: isLoadingModels } = useQuery<{
    items: Model[]
    total: number
    backends: BackendOption[]
  }>({
    queryKey: ['models', pagination, filters, sorting],
    queryFn: async () => {
      const res = await api.get('/admin/models', {
        params: {
          page: pagination.pageIndex + 1,
          limit: pagination.pageSize,
          ...filters
        }
      })
      const payload = res.data as Model[] | ModelsResponse
      if (Array.isArray(payload)) {
        return { items: payload, total: payload.length, backends: [] }
      }

      const items = Array.isArray(payload?.registry)
        ? payload.registry
        : Array.isArray(payload?.items)
          ? payload.items
          : []

      return {
        items,
        total: typeof payload?.total === 'number' ? payload.total : items.length,
        backends: Array.isArray(payload?.backends) ? payload.backends : [],
      }
    }
  })

  const { data: runtimes } = useQuery<ModelRuntimeInstance[]>({
    queryKey: ['model-runtimes'],
    queryFn: async () => {
      const res = await api.get('/admin/models/runtime')
      return res.data
    },
    refetchInterval: 5000
  })

  const { data: backendsData } = useQuery<BackendOption[]>({
    queryKey: ['backends-options'],
    queryFn: async () => {
      const res = await api.get('/admin/backends', { params: { page: 1, limit: 200 } })
      return Array.isArray(res.data) ? res.data : Array.isArray(modelsData?.backends) ? modelsData.backends : []
    }
  })

  const backendOptions = backendsData || modelsData?.backends || []

  const toggleMutation = useMutation({
    mutationFn: async ({ id, enabled }: { id: string, enabled: boolean }) => {
      const action = enabled ? 'disable' : 'enable'
      return api.post(`/admin/models/${id}/${action}`)
    },
    onSuccess: (_, variables) => {
      queryClient.invalidateQueries({ queryKey: ['models'] })
      toast.success(`Modelo ${variables.enabled ? 'desativado' : 'ativado'} com sucesso!`)
    }
  })

  const createModelMutation = useMutation({
    mutationFn: async () => {
      const payload: Record<string, any> = {
        display_name: createForm.display_name.trim() || null,
        model_id: createForm.model_id.trim(),
        model_alias: createForm.model_alias.trim() || null,
        inference_backend_id: createForm.inference_backend_id || null,
        provider: createForm.provider,
        model_file: createForm.model_file.trim(),
        context_length: Number(createForm.context_length) || 4096,
        is_active: createForm.is_active,
        is_default: createForm.is_default,
        status: createForm.status,
        allow_reasoning: createForm.allow_reasoning,
        include_reasoning_default: createForm.include_reasoning_default,
        prompt_template: createForm.prompt_template.trim() || null,
      }
      const res = await api.post('/admin/models', payload)
      return res.data as Model
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['models'] })
      setIsCreateOpen(false)
      setCreateForm({
        display_name: '',
        model_id: '',
        model_alias: '',
        inference_backend_id: '',
        provider: 'llama.cpp',
        model_file: '',
        context_length: 4096,
        is_active: true,
        is_default: false,
        status: 'configured',
        allow_reasoning: true,
        include_reasoning_default: false,
        prompt_template: '',
      })
      toast.success('Modelo registrado com sucesso!')
    },
    onError: (error: any) => {
      toast.error(error?.response?.data?.detail || 'Falha ao registrar modelo')
    }
  })

  const getRuntimesForModel = (modelId: string) => runtimes?.filter(r => r.model_id === modelId) || []

  const columns: ColumnDef<Model>[] = [
    {
      accessorKey: 'display_name',
      header: 'Modelo',
      cell: ({ row }) => (
        <div className="flex items-center gap-3">
          <div className="p-2 bg-secondary rounded-lg">
            <Box className="w-4 h-4 text-primary" />
          </div>
          <div>
            <div className="font-bold text-foreground">{row.original.display_name}</div>
            <div className="text-[10px] font-mono text-muted-foreground">{row.original.model_id}</div>
          </div>
        </div>
      )
    },
    {
      accessorKey: 'provider',
      header: 'Provider',
      cell: ({ row }) => (
        <span className="px-2 py-0.5 bg-secondary text-muted-foreground text-[10px] font-black rounded-md uppercase">
          {row.original.provider}
        </span>
      )
    },
    {
      id: 'runtime',
      header: 'Runtime Status',
      cell: ({ row }) => {
        const modelRuntimes = getRuntimesForModel(row.original.id)
        const activeRuntime = modelRuntimes.find(r => r.is_active)
        return (
          <div className="flex flex-col gap-1">
            {activeRuntime ? (
              <span className="inline-flex items-center gap-1 text-emerald-600 text-[10px] font-black uppercase">
                <Zap className="w-3 h-3" /> {activeRuntime.status}
              </span>
            ) : (
              <span className="text-muted-foreground text-[10px] font-black uppercase tracking-tight">Standby</span>
            )}
          </div>
        )
      }
    },
    {
      accessorKey: 'is_active',
      header: 'Estado',
      cell: ({ row }) => row.original.is_active ? (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-emerald-500/10 text-emerald-600 text-[10px] font-black rounded-md">
          <CheckCircle2 className="w-3 h-3" /> ONLINE
        </span>
      ) : (
        <span className="inline-flex items-center gap-1 px-2 py-0.5 bg-secondary text-muted-foreground text-[10px] font-black rounded-md">
          <XCircle className="w-3 h-3" /> OFFLINE
        </span>
      )
    },
    {
      id: 'actions',
      header: 'Ações',
      cell: ({ row }) => (
        <div className="flex gap-2 justify-end">
          <button 
            onClick={() => toggleMutation.mutate({ id: row.original.id, enabled: row.original.is_active })}
            className="p-2 hover:bg-secondary rounded-lg text-muted-foreground transition-all"
          >
            {row.original.is_active ? <PowerOff className="w-4 h-4" /> : <Power className="w-4 h-4 text-primary" />}
          </button>
          <button className="p-2 hover:bg-secondary rounded-lg text-muted-foreground transition-all">
            <Settings2 className="w-4 h-4" />
          </button>
        </div>
      ),
      enableHiding: false,
    }
  ]

  const batchActions = [
    {
      label: 'Habilitar Selecionados',
      icon: <Power size={14} />,
      onClick: (rows: Model[]) => toast.success(`${rows.length} modelos habilitados`),
    },
    {
      label: 'Desabilitar Selecionados',
      icon: <PowerOff size={14} />,
      onClick: (rows: Model[]) => toast.success(`${rows.length} modelos desabilitados`),
      variant: 'destructive' as const
    },
    {
      label: 'Excluir Registros',
      icon: <Trash2 size={14} />,
      onClick: (rows: Model[]) => toast.error('Exclusão de modelos não permitida via lote.'),
      variant: 'destructive' as const
    }
  ]

  const filterConfig = [
    { id: 'display_name', label: 'Nome do Modelo', type: 'text' },
    { 
      id: 'provider', 
      label: 'Provider', 
      type: 'select',
      options: [
        { label: 'OpenAI', value: 'openai' },
        { label: 'Anthropic', value: 'anthropic' },
        { label: 'Local (Llama)', value: 'local' }
      ]
    },
    { 
      id: 'is_active', 
      label: 'Estado', 
      type: 'status',
      options: [
        { label: 'Online', value: 'true' },
        { label: 'Offline', value: 'false' }
      ]
    }
  ]

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-foreground mb-1">Catálogo de Modelos</h1>
          <p className="text-muted-foreground text-sm md:text-lg">Configuração de LLMs, precificação e roteamento padrão.</p>
        </div>
        <button
          onClick={() => setIsCreateOpen(true)}
          className="bg-primary hover:bg-primary/90 text-white px-4 py-2.5 rounded-xl font-bold flex items-center justify-center gap-2 transition-colors shadow-lg shadow-primary/20 w-full sm:w-auto"
        >
          <Plus className="w-5 h-5" />
          Registrar Modelo
        </button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3 md:gap-4">
        <div className="bg-card p-4 md:p-6 rounded-2xl border border-border shadow-sm" role="status">
          <h2 className="text-muted-foreground text-[10px] font-black uppercase tracking-widest mb-1 md:mb-2">Total</h2>
          <div className="text-xl md:text-3xl font-black text-foreground">{modelsData?.total || 0}</div>
        </div>
        <div className="bg-card p-4 md:p-6 rounded-2xl border border-border shadow-sm" role="status">
          <h2 className="text-muted-foreground text-[10px] font-black uppercase tracking-widest mb-1 md:mb-2">Ativos</h2>
          <div className="text-xl md:text-3xl font-black text-primary">{modelsData?.items?.filter((m: Model) => m.is_active).length || 0}</div>
        </div>
        <div className="bg-card p-4 md:p-6 rounded-2xl border border-border shadow-sm" role="status">
          <h2 className="text-muted-foreground text-[10px] font-black uppercase tracking-widest mb-1 md:mb-2">Providers</h2>
          <div className="text-xl md:text-3xl font-black text-foreground">{new Set(modelsData?.items?.map((m: Model) => m.provider)).size || 0}</div>
        </div>
        <div className="bg-card p-4 md:p-6 rounded-2xl border border-border shadow-sm" role="status">
          <h2 className="text-muted-foreground text-[10px] font-black uppercase tracking-widest mb-1 md:mb-2">Runtimes</h2>
          <div className="text-xl md:text-3xl font-black text-yellow-500">{runtimes?.filter(r => r.status === 'ready').length || 0}</div>
        </div>
      </div>

      <AdvancedTable
        id="models"
        columns={columns}
        data={modelsData?.items || []}
        rowCount={modelsData?.total || 0}
        isLoading={isLoadingModels}
        pagination={pagination}
        onPaginationChange={setPagination}
        onSortingChange={setSorting}
        onFiltersApply={setFilters}
        filterConfig={filterConfig}
        batchActions={batchActions}
      />

      {isCreateOpen && (
        <div className="fixed inset-0 z-[110] bg-foreground/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="w-full max-w-3xl rounded-3xl border border-border bg-card shadow-2xl overflow-hidden">
            <div className="flex items-center justify-between gap-4 border-b border-border px-6 py-4">
              <div>
                <h2 className="text-xl font-black text-foreground">Registrar Modelo</h2>
