    { score: 0.95, passRate: 1.0, version: "1.0.0", createdAt: "2026-05-21T08:00:00Z" },
    { score: 0.75, passRate: 0.7, version: "0.9.0", createdAt: "2026-05-20T08:00:00Z" },
