import React from 'react';
import { Box, Typography, Paper } from '@mui/material';

const TraceInspector: React.FC<{ events?: any[] }> = ({ events }) => (
  <Box sx={{ p: 2 }}>
    <Typography variant="overline">Trace Inspector</Typography>
    <Paper variant="outlined" sx={{ maxHeight: 300, overflow: 'auto', p: 1, bgcolor: 'grey.900', color: 'common.white', fontFamily: 'monospace', fontSize: '0.75rem' }}>
      {(events || [
        { time: "10:00:01", msg: "Event: run_started" },
        { time: "10:00:05", msg: "Event: thought_generated", summary: "Analyzing the user request..." }
      ]).map((e, i) => (
        <Box key={i} sx={{ mb: 1 }}>
          <Typography variant="caption" color="grey.500">[{e.time}] </Typography>
          <Typography variant="caption" sx={{ color: 'primary.light' }}>{e.msg} </Typography>
          {e.summary && <Typography variant="caption" sx={{ color: 'grey.300' }}>- {e.summary}</Typography>}
        </Box>
      ))}
    </Paper>
  </Box>
);

export default TraceInspector;

import { useEffect, useMemo, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '../../components/card'
import { Badge } from '../../components/badge'
import { Button } from '../../components/button'
import api from '../../lib/api'
import { Key, Copy, Trash2, RotateCcw, Plus, UserRound } from 'lucide-react'
import { toast } from 'sonner'
import { APIError } from '../../lib/api'

interface ApiKey {
  id: string
  client_id: string
  client_name?: string
  plan_name?: string
  name: string
  key_prefix: string
  created_at: string
  expires_at: string | null
  last_used_at: string | null
  revoked_at: string | null
  is_active: boolean
}

interface ClientOption {
  id: string
  name: string
  billing_status?: string
}

function extractSecret(result: any): string | null {
  return result?.api_key?.api_key || result?.api_key || result?.key || null
}

export default function ApiKeys() {
  const [keys, setKeys] = useState<ApiKey[]>([])
  const [clients, setClients] = useState<ClientOption[]>([])
  const [loading, setLoading] = useState(true)
  const [rotatingId, setRotatingId] = useState<string | null>(null)
  const [newKey, setNewKey] = useState<string | null>(null)
  const [isCreateOpen, setIsCreateOpen] = useState(false)
  const [createClientId, setCreateClientId] = useState('')
  const [createName, setCreateName] = useState('')

  const fetchKeys = async () => {
    try {
      const data = await api.listApiKeys()
      setKeys(data)
    } catch {
      toast.error('Falha ao carregar API keys')
    } finally {
      setLoading(false)
    }
  }

  const fetchClients = async () => {
    try {
      const data: any = await api.listClients()
      setClients(Array.isArray(data) ? data : data?.items || [])
    } catch {
      toast.error('Falha ao carregar clientes')
    }
  }

  useEffect(() => {
    fetchKeys()
    fetchClients()
  }, [])

  useEffect(() => {
    if (!createClientId && clients.length > 0) {
      setCreateClientId(clients[0].id)
    }
  }, [clients, createClientId])

  const handleCreate = async () => {
    try {
      if (!createClientId) {
        toast.error('Selecione um cliente')
        return
      }
      if (!createName.trim()) {
        toast.error('Informe o nome da chave')
        return
      }
      const result = await api.createApiKey({ client_id: createClientId, name: createName.trim() })
      const secret = extractSecret(result)
      setNewKey(secret)
      toast.success('Chave criada')
      setIsCreateOpen(false)
      setCreateName('')
      fetchKeys()
    } catch {
      toast.error('Falha ao criar chave')
    }
  }

  const handleRotate = async (id: string) => {
    const current = keys.find(key => key.id === id)
    if (current?.revoked_at) {
      toast.error('Chave revogada não pode ser rotacionada')
      return
    }

    try {
      setRotatingId(id)
      const result = await api.rotateApiKey(id)
      const secret = extractSecret(result)
      if (!secret) {
        throw new Error('Backend não retornou a nova chave')
      }
      setNewKey(secret)
      toast.success('Chave rotacionada')
      window.scrollTo({ top: 0, behavior: 'smooth' })
      await fetchKeys()
    } catch (error) {
      if (error instanceof APIError) {
        toast.error((error.data as any)?.detail || error.message || 'Falha ao rotacionar')
        return
      }
      toast.error(error instanceof Error ? error.message : 'Falha ao rotacionar')
    } finally {
      setRotatingId(null)
    }
  }

  const handleDelete = async (id: string) => {
    if (!confirm('Excluir esta chave API?')) return
    try {
      await api.deleteApiKey(id)
      toast.success('Chave excluída')
      fetchKeys()
    } catch {
      toast.error('Falha ao excluir')
    }
  }

  const selectedClient = useMemo(
    () => clients.find(client => client.id === createClientId),
    [clients, createClientId],
  )

  return (
    <div className="p-6 space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">API Keys</h1>
          <p className="text-muted-foreground">Gerencie chaves de API para integrações</p>
        </div>
        <Button onClick={() => setIsCreateOpen(true)}>
          <Plus className="w-4 h-4 mr-2" /> Nova Chave
        </Button>
      </div>

      {newKey && (
        <Card className="border-yellow-500/50 bg-yellow-500/5">
          <CardHeader>
            <CardTitle className="text-yellow-600">Chave gerada - copie agora!</CardTitle>
          </CardHeader>
          <CardContent>
            <code className="block p-3 bg-muted rounded text-sm break-all">{newKey}</code>
            <Button
              variant="outline"
              size="sm"
              className="mt-2"
              onClick={() => {
                navigator.clipboard.writeText(newKey)
                toast.success('Copiado')
              }}
            >
              <Copy className="w-4 h-4 mr-2" /> Copiar
            </Button>
          </CardContent>
        </Card>
      )}

      {loading ? (
        <p className="text-muted-foreground">Carregando...</p>
      ) : (
        <div className="space-y-3">
          {keys.map(k => (
            <Card key={k.id}>
              <CardContent className="flex flex-col gap-4 p-4 lg:flex-row lg:items-center lg:justify-between">
                <div className="flex items-center gap-3">
                  <Key className="w-5 h-5 text-muted-foreground" />
                  <div>
                    <p className="font-medium text-foreground">{k.name}</p>
                    <p className="text-sm text-muted-foreground">
                      {k.client_name || k.client_id} · {k.key_prefix}... | criada {new Date(k.created_at).toLocaleDateString()}
                    </p>
                    <p className="text-[10px] uppercase font-black tracking-widest text-muted-foreground">
                      {k.plan_name || 'N/A'} · {k.revoked_at ? 'Revogada' : k.is_active ? 'Ativa' : 'Inativa'}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge variant={k.revoked_at ? 'destructive' : k.is_active ? 'default' : 'secondary'}>
                    {k.revoked_at ? 'Revogada' : k.is_active ? 'Ativa' : 'Inativa'}
                  </Badge>
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => handleRotate(k.id)}
                    isLoading={rotatingId === k.id}
                    title={k.revoked_at ? 'Chave revogada' : 'Rotacionar'}
                    disabled={Boolean(k.revoked_at)}
                  >
                    <RotateCcw className="w-4 h-4" />
                  </Button>
                  <Button variant="outline" size="icon" onClick={() => handleDelete(k.id)} title="Excluir">
                    <Trash2 className="w-4 h-4" />
                  </Button>
                </div>
              </CardContent>
            </Card>
          ))}
          {keys.length === 0 && <p className="text-muted-foreground text-center py-8">Nenhuma chave API cadastrada.</p>}
        </div>
      )}

      {isCreateOpen && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center bg-foreground/60 p-4 backdrop-blur-sm">
          <div className="w-full max-w-xl rounded-3xl border border-border bg-card shadow-2xl">
            <div className="flex items-start justify-between gap-4 border-b border-border px-6 py-5">
              <div>
                <h2 className="text-xl font-black text-foreground">Nova Chave</h2>
                <p className="text-sm text-muted-foreground">Cria uma API key para um cliente existente.</p>
              </div>
              <button
                onClick={() => setIsCreateOpen(false)}
                className="rounded-xl border border-border px-3 py-2 text-sm font-bold text-muted-foreground hover:bg-secondary hover:text-foreground"
              >
                Fechar
              </button>
            </div>

            <div className="space-y-4 px-6 py-5">
              <label className="space-y-2 block">
                <span className="text-xs font-black uppercase tracking-widest text-muted-foreground">Cliente</span>
                <select
                  value={createClientId}
                  onChange={e => setCreateClientId(e.target.value)}
                  className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
                >
                  <option value="">Selecione um cliente</option>
                  {clients.map(client => (
                    <option key={client.id} value={client.id}>
                      {client.name} {client.billing_status ? `· ${client.billing_status}` : ''}
                    </option>
                  ))}
                </select>
              </label>

              <label className="space-y-2 block">
                <span className="text-xs font-black uppercase tracking-widest text-muted-foreground">Nome da chave</span>
                <input
                  value={createName}
                  onChange={e => setCreateName(e.target.value)}
                  className="w-full rounded-2xl border border-border bg-background px-4 py-3 text-sm text-foreground outline-none focus:border-primary"
                  placeholder="Ex: integração backend"
                />
              </label>

              {selectedClient && (
                <div className="flex items-center gap-2 rounded-2xl border border-border bg-secondary/40 px-4 py-3 text-sm text-muted-foreground">
                  <UserRound className="h-4 w-4" />
                  {selectedClient.name}
                </div>
              )}
            </div>

            <div className="flex items-center justify-end gap-3 border-t border-border px-6 py-4">
              <Button variant="outline" onClick={() => setIsCreateOpen(false)}>
                Cancelar
              </Button>
              <Button onClick={handleCreate} disabled={!createClientId || !createName.trim()}>
                Criar chave
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

import { useMemo, useState, type ReactNode } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { CreditCard, DollarSign, FileText, Layers3, PlayCircle, RefreshCw, Wallet } from 'lucide-react'
import { toast } from 'sonner'

import api from '../../lib/api'

type BillingTab = 'overview' | 'plans' | 'pricing' | 'invoices' | 'payments'

function formatTokenLimit(value: number | null | undefined) {
  return value && value > 0 ? value.toLocaleString() : 'Ilimitado'
}

export default function Billing() {
  const queryClient = useQueryClient()
  const [tab, setTab] = useState<BillingTab>('overview')

  const { data: revenueSummary } = useQuery({
    queryKey: ['billing-revenue-summary'],
    queryFn: () => api.getRevenueSummary(),
  })

  const { data: invoicePreview } = useQuery({
    queryKey: ['billing-invoice-preview'],
    queryFn: () => api.previewInvoices(),
  })

  const { data: plans = [] } = useQuery({
    queryKey: ['billing-plans-admin'],
    queryFn: () => api.listBillingPlansAdmin(),
  })

  const { data: pricingRules = [] } = useQuery({
    queryKey: ['billing-pricing-rules'],
    queryFn: () => api.listPricingRules(),
  })

  const { data: invoices = [] } = useQuery({
    queryKey: ['billing-invoices'],
    queryFn: () => api.listInvoices(),
  })

  const { data: payments = [] } = useQuery({
    queryKey: ['billing-payments'],
    queryFn: () => api.listPayments(),
  })

  const generateInvoicesMutation = useMutation({
    mutationFn: () => api.generateInvoices({ due_in_days: 7, payment_method: 'manual', payment_instructions: 'Emitido pelo dashboard administrativo.' }),
    onSuccess: () => {
      toast.success('Geracao de faturas concluida.')
      invalidateBilling(queryClient)
    },
    onError: (error: any) => toast.error(error?.message || 'Falha ao gerar faturas'),
  })

  const runCycleMutation = useMutation({
    mutationFn: () => api.runBillingCycle(),
    onSuccess: () => {
      toast.success('Ciclo de billing executado.')
      invalidateBilling(queryClient)
    },
    onError: (error: any) => toast.error(error?.message || 'Falha ao executar ciclo'),
  })

  const monthlyRevenue = Number(revenueSummary?.monthly_revenue || 0)
  const totalRevenue = Number(revenueSummary?.total_revenue || 0)
  const pendingInvoices = Number(revenueSummary?.pending_invoices || 0)
  const previewClients = Array.isArray(invoicePreview?.clients) ? invoicePreview.clients : []

  const tabs: Array<{ id: BillingTab; label: string }> = useMemo(() => ([
    { id: 'overview', label: 'Overview' },
    { id: 'plans', label: 'Plans' },
    { id: 'pricing', label: 'Pricing Rules' },
    { id: 'invoices', label: 'Invoices' },
    { id: 'payments', label: 'Payments' },
  ]), [])

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold text-foreground">Billing</h1>
          <p className="text-sm md:text-lg text-muted-foreground">Dashboard administrativo de receita, planos, precificacao, faturas e pagamentos.</p>
        </div>
        <div className="flex flex-col gap-3 sm:flex-row">
          <button
            type="button"
            onClick={() => invalidateBilling(queryClient)}
            className="rounded-xl border border-border px-4 py-2.5 text-sm font-bold text-foreground hover:bg-secondary"
          >
            Atualizar
          </button>
          <button
            type="button"
            onClick={() => generateInvoicesMutation.mutate()}
            disabled={generateInvoicesMutation.isPending}
            className="rounded-xl border border-border px-4 py-2.5 text-sm font-bold text-foreground hover:bg-secondary disabled:opacity-50"
          >
            {generateInvoicesMutation.isPending ? 'Gerando...' : 'Gerar Faturas'}
          </button>
          <button
            type="button"
            onClick={() => runCycleMutation.mutate()}
            disabled={runCycleMutation.isPending}
            className="flex items-center justify-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-white shadow-lg shadow-primary/20 hover:bg-primary/90 disabled:opacity-50"
          >
            <PlayCircle className="h-4 w-4" />
            {runCycleMutation.isPending ? 'Executando...' : 'Run Cycle'}
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <MetricCard label="Receita Total" value={`R$ ${totalRevenue.toFixed(2)}`} icon={<DollarSign className="h-5 w-5 text-emerald-500" />} />
        <MetricCard label="Mes Atual" value={`R$ ${monthlyRevenue.toFixed(2)}`} icon={<Wallet className="h-5 w-5 text-primary" />} />
        <MetricCard label="Pendentes" value={String(pendingInvoices)} icon={<FileText className="h-5 w-5" />} />
        <MetricCard label="Planos" value={String(plans.length)} icon={<Layers3 className="h-5 w-5" />} />
      </div>

      <div className="flex flex-wrap gap-2">
        {tabs.map(item => (
          <button
            key={item.id}
            type="button"
            onClick={() => setTab(item.id)}
            className={`rounded-full px-4 py-2 text-xs font-black uppercase tracking-wider transition-all ${
              tab === item.id ? 'bg-primary text-white' : 'bg-secondary text-muted-foreground hover:text-foreground'
            }`}
          >
            {item.label}
          </button>
        ))}
      </div>

      {tab === 'overview' && (
        <div className="grid gap-6 xl:grid-cols-[1.1fr,0.9fr]">
          <section className="rounded-3xl border border-border bg-card p-5 shadow-sm">
            <div className="mb-4 flex items-center gap-2 text-lg font-black text-foreground">
              <RefreshCw className="h-5 w-5 text-primary" />
              Preview de Faturas
            </div>
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="border-b border-border text-left text-xs font-black uppercase tracking-widest text-muted-foreground">
                    <th className="py-3 pr-4">Cliente</th>
                    <th className="py-3 pr-4">Plano</th>
                    <th className="py-3 pr-4">Preview</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {previewClients.map((item: any) => (
                    <tr key={item.client_id}>
                      <td className="py-3 pr-4 font-semibold text-foreground">{item.name}</td>
                      <td className="py-3 pr-4 text-muted-foreground">{item.billing_plan_code}</td>
                      <td className="py-3 pr-4 text-xs font-mono text-foreground">{JSON.stringify(item.invoice_preview)}</td>
                    </tr>
                  ))}
                  {previewClients.length === 0 && (
                    <tr>
                      <td colSpan={3} className="py-8 text-center text-muted-foreground">Nenhum preview disponivel.</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          </section>

          <section className="rounded-3xl border border-border bg-card p-5 shadow-sm">
            <div className="mb-4 flex items-center gap-2 text-lg font-black text-foreground">
              <CreditCard className="h-5 w-5 text-primary" />
              Resumo
            </div>
            <div className="space-y-4">
              <SummaryRow label="Receita total" value={`R$ ${totalRevenue.toFixed(2)}`} />
              <SummaryRow label="Receita mensal" value={`R$ ${monthlyRevenue.toFixed(2)}`} />
              <SummaryRow label="Faturas pendentes" value={String(pendingInvoices)} />
              <SummaryRow label="Payments registrados" value={String(payments.length)} />
              <SummaryRow label="Invoices registradas" value={String(invoices.length)} />
            </div>
          </section>
        </div>
      )}

      {tab === 'plans' && (
        <DataCard title="Billing Plans">
          <SimpleTable
            headers={['Code', 'Nome', 'Limite RPM', 'Tokens/Dia', 'Modelos']}
            rows={plans.map((plan: any) => [
              plan.code,
              plan.name || '-',
              String(plan.rate_limit_per_minute ?? '-'),
              formatTokenLimit(plan.daily_token_quota),
              Array.isArray(plan.allowed_models) ? plan.allowed_models.join(', ') : plan.allowed_models_json || '-',
            ])}
            emptyLabel="Nenhum plano encontrado."
          />
        </DataCard>
      )}

      {tab === 'pricing' && (
        <DataCard title="Pricing Rules">
          <SimpleTable
            headers={['Billing Plan', 'Currency', 'Monthly', 'Overage / 1k', 'Ativa']}
            rows={pricingRules.map((rule: any) => [
              String(rule.billing_plan_id),
              rule.currency,
              String(rule.monthly_price),
              String(rule.overage_price_per_1k_tokens),
              rule.is_active ? 'sim' : 'nao',
            ])}
            emptyLabel="Nenhuma regra de preco encontrada."
          />
        </DataCard>
      )}

      {tab === 'invoices' && (
        <DataCard title="Invoices">
          <SimpleTable
            headers={['ID', 'Client', 'Amount', 'Status', 'Due Date']}
            rows={invoices.map((invoice: any) => [
              String(invoice.id).slice(0, 12),
              invoice.client_id || '-',
              String(invoice.amount ?? invoice.total_amount ?? '-'),
              invoice.status || '-',
              invoice.due_date ? new Date(invoice.due_date).toLocaleDateString() : '-',
            ])}
            emptyLabel="Nenhuma fatura encontrada."
          />
        </DataCard>
      )}

      {tab === 'payments' && (
        <DataCard title="Payments">
          <SimpleTable
            headers={['ID', 'Invoice', 'Amount', 'Status', 'Metodo']}
            rows={payments.map((payment: any) => [
              String(payment.id).slice(0, 12),
              payment.invoice_id || '-',
              String(payment.amount ?? '-'),
              payment.status || '-',
              payment.payment_method || '-',
            ])}
            emptyLabel="Nenhum pagamento encontrado."
          />
        </DataCard>
      )}
    </div>
  )
}

function invalidateBilling(queryClient: ReturnType<typeof useQueryClient>) {
  queryClient.invalidateQueries({ queryKey: ['billing-revenue-summary'] })
  queryClient.invalidateQueries({ queryKey: ['billing-invoice-preview'] })
  queryClient.invalidateQueries({ queryKey: ['billing-plans-admin'] })
  queryClient.invalidateQueries({ queryKey: ['billing-pricing-rules'] })
  queryClient.invalidateQueries({ queryKey: ['billing-invoices'] })
  queryClient.invalidateQueries({ queryKey: ['billing-payments'] })
}

function MetricCard({ label, value, icon }: { label: string; value: string; icon: ReactNode }) {
  return (
    <div className="rounded-2xl border border-border bg-card p-4 shadow-sm">
      <div className="mb-2 flex items-center gap-3 text-muted-foreground">{icon}</div>
      <div className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</div>
      <div className="text-2xl font-black text-foreground">{value}</div>
    </div>
  )
}

function DataCard({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="rounded-3xl border border-border bg-card p-5 shadow-sm">
      <div className="mb-4 text-lg font-black text-foreground">{title}</div>
      {children}
    </section>
  )
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between rounded-2xl border border-border bg-background px-4 py-3">
      <span className="text-sm text-muted-foreground">{label}</span>
      <span className="text-sm font-black text-foreground">{value}</span>
    </div>
  )
}

function SimpleTable({ headers, rows, emptyLabel }: { headers: string[]; rows: string[][]; emptyLabel: string }) {
  return (
    <div className="overflow-x-auto">
      <table className="min-w-full text-sm">
        <thead>
          <tr className="border-b border-border text-left text-xs font-black uppercase tracking-widest text-muted-foreground">
            {headers.map(header => (
              <th key={header} className="py-3 pr-4">{header}</th>
            ))}
          </tr>
        </thead>
        <tbody className="divide-y divide-border">
          {rows.map((row, rowIndex) => (
            <tr key={rowIndex}>
              {row.map((value, cellIndex) => (
                <td key={cellIndex} className="py-3 pr-4 text-foreground">{value}</td>
              ))}
            </tr>
          ))}
          {!rows.length && (
            <tr>
              <td colSpan={headers.length} className="py-8 text-center text-muted-foreground">{emptyLabel}</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  )
}

import React, { useState, useEffect } from 'react';

interface AgentMentionPickerProps {
  onSelect: (agent: any) => void;
  filter: string;
}

const AgentMentionPicker: React.FC<AgentMentionPickerProps> = ({ onSelect, filter }) => {
  const [agents, setAgents] = useState<any[]>([]);

  useEffect(() => {
    // In a real app, we'd fetch agents from the API
    setAgents([
      { id: 'agent-1-uuid', name: 'Suporte' },
      { id: 'agent-2-uuid', name: 'Analista' },
    ]);
  }, []);

  const filtered = agents.filter(a => a.name.toLowerCase().includes(filter.toLowerCase()));

  if (filtered.length === 0) return null;

  return (
    <div className="absolute bottom-full left-0 mb-2 w-64 bg-white border rounded shadow-lg overflow-hidden z-50">
      <div className="p-2 bg-gray-50 text-xs font-bold text-gray-500 uppercase">Mencionar Agente</div>
      {filtered.map(agent => (
        <button
          key={agent.id}
          className="w-full text-left px-4 py-2 hover:bg-blue-50 transition"
          onClick={() => onSelect(agent)}
        >
          <div className="font-medium">@{agent.name}</div>
        </button>
      ))}
    </div>
  );
};

export default AgentMentionPicker;

