import React, { useState, useEffect } from 'react';
import FileExplorer from './FileExplorer';
import CodeEditor from './CodeEditor';
import TerminalPanel from './TerminalPanel';
import AgentManifestEditor from './AgentManifestEditor';
import PluginManifestEditor from './PluginManifestEditor';

const WebIDE: React.FC = () => {
  const [activeFile, setActiveFile] = useState<string | null>(null);
  const [fileContent, setFileContent] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [clientToken, setClientToken] = useState(() => localStorage.getItem('webIdeClientToken') || '');
  const [inputValue, setInputValue] = useState(() => localStorage.getItem('webIdeClientToken') || '');
  const [workspaceState, setWorkspaceState] = useState<{ loading: boolean; error: string | null }>({ loading: false, error: null });

  useEffect(() => {
    localStorage.setItem('webIdeClientToken', clientToken);
  }, [clientToken]);

  useEffect(() => {
    if (!clientToken) {
      setActiveFile(null);
      setFileContent('');
      setWorkspaceState({ loading: false, error: null });
    }
  }, [clientToken]);

  const handleApplyToken = () => {
    setClientToken(inputValue.trim());
  };

  const handleClearToken = () => {
    setInputValue('');
    setClientToken('');
  };

  const handleFileSelect = (path: string) => {
    if (!clientToken) return;
    setWorkspaceState({ loading: true, error: null });
    fetch(`/v1/ide/files/read?path=${encodeURIComponent(path)}`, {
      headers: { Authorization: `Bearer ${clientToken}` }
    })
      .then(async res => {
        const payload = await res.json().catch(() => ({}));
        if (!res.ok) {
          throw new Error(payload?.detail || `Falha HTTP ${res.status}`);
        }
        return payload;
      })
      .then(data => {
        setActiveFile(path);
        setFileContent(data.content || '');
        setWorkspaceState({ loading: false, error: null });
      })
      .catch(err => {
        setWorkspaceState({ loading: false, error: err.message || 'Falha ao abrir arquivo.' });
      });
  };

  const handleSave = () => {
    if (!activeFile || !clientToken) return;
    setIsSaving(true);
    fetch('/v1/ide/files/write', {
      method: 'POST',
      headers: { 
        'Authorization': `Bearer ${clientToken}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ path: activeFile, content: fileContent })
    })
      .finally(() => setIsSaving(false));
  };

  return (
    <div className="flex h-screen bg-slate-950 text-white overflow-hidden">
      <div className="w-full flex flex-col">
        <header className="border-b border-white/10 bg-slate-900/80 px-6 py-4 backdrop-blur flex flex-wrap items-center justify-between gap-4">
          <div>
            <div className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-300">Web IDE</div>
            <h1 className="text-xl font-black">Workspace do cliente</h1>
            <p className="text-sm text-slate-400">Use uma API key de cliente para abrir arquivos, salvar manifests e rodar comandos restritos.</p>
          </div>
          <div className="grid gap-2 min-w-[320px]">
            <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Client API Key</span>
            <div className="flex gap-2">
              <input
                className="flex-1 rounded-xl border border-white/10 bg-slate-950 px-4 py-2 text-sm text-white outline-none focus:border-blue-400"
                type="password"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Bearer token do cliente"
              />
              <button 
                onClick={handleApplyToken}
                className="bg-blue-600 hover:bg-blue-500 px-4 py-2 text-sm font-bold rounded-xl transition-colors"
              >
                Aplicar
              </button>
              <button 
                onClick={handleClearToken}
                className="bg-slate-800 hover:bg-slate-700 px-4 py-2 text-sm font-bold rounded-xl transition-colors border border-white/10"
              >
                Limpar
              </button>
            </div>
          </div>
        </header>

        <div className="flex flex-1 overflow-hidden">
          <div className="w-72 border-r border-white/10 bg-slate-900/60 flex flex-col">
            <div className="p-4 font-black border-b border-white/10 text-sm uppercase tracking-widest text-slate-300">Workspace</div>
            <div className="flex-1 overflow-y-auto">
              <FileExplorer
                token={clientToken || null}
                onSelect={handleFileSelect}
                activeFile={activeFile}
                onStatusChange={setWorkspaceState}
              />
            </div>
          </div>

          <div className="flex-1 flex flex-col min-w-0">
            <div className="h-10 bg-slate-900 flex items-center px-4 justify-between border-b border-white/10">
              <div className="text-sm text-slate-400 truncate">
                {workspaceState.loading ? 'Carregando...' : workspaceState.error || activeFile || 'Nenhum arquivo selecionado'}
              </div>
              <button
                onClick={handleSave}
                disabled={!activeFile || !clientToken || isSaving}
                className="text-xs bg-blue-600 hover:bg-blue-500 px-3 py-1 rounded disabled:opacity-50"
              >
                {isSaving ? 'Salvando...' : 'Salvar (Ctrl+S)'}
              </button>
            </div>

            <div className="flex-1 flex overflow-hidden">
              <div className="flex-1 overflow-hidden border-r border-white/10">
                {!activeFile ? (
                  <div className="h-full flex items-center justify-center bg-slate-950 px-8 text-center">
                    {clientToken ? (
                      <div className="max-w-lg">
                        <div className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-300 mb-3">Conectado ao Workspace</div>
                        <h2 className="text-2xl font-black mb-3">Selecione um arquivo</h2>
                        <p className="text-slate-400 leading-relaxed">
                          O workspace já está disponível. Escolha um arquivo na barra lateral para abrir o editor e o terminal restrito. Você pode precisar expandir as pastas para ver os arquivos.
                        </p>
                      </div>
                    ) : (
                      <div className="max-w-lg">
                        <div className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-300 mb-3">Preparado, mas não conectado</div>
                        <h2 className="text-2xl font-black mb-3">Informe uma API key de cliente</h2>
                        <p className="text-slate-400 leading-relaxed">
                          O Web IDE trabalha sobre workspaces de tenant. Sem um bearer token de cliente, a tela fica em modo explicativo e não tenta acessar arquivos ou terminal.
                        </p>
                      </div>
                    )}
                  </div>
                ) : activeFile?.endsWith('.yaml') && activeFile.includes('agents/') ? (
                  <AgentManifestEditor content={fileContent} onChange={setFileContent} />
                ) : activeFile?.endsWith('.yaml') && activeFile.includes('plugins/') ? (
                  <PluginManifestEditor content={fileContent} onChange={setFileContent} />
                ) : (
                  <CodeEditor content={fileContent} onChange={setFileContent} />
                )}
              </div>
            </div>

            <div className="h-64 border-t border-white/10">
              <TerminalPanel token={clientToken || null} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default WebIDE;

import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../../components/card'
import { Badge } from '../../components/badge'
import { Button } from '../../components/button'
import { Input } from '../../components/input'
import api from '../../lib/api'
import { 
  ShoppingBag, 
  ShieldCheck, 
  ShieldAlert, 
  Download, 
  ExternalLink,
  Info
} from 'lucide-react'
import { toast } from 'sonner'

export default function AgentMarketplace() {
  const [agents, setAgents] = useState<any[]>([])
  const [loading, setLoading] = useState(true)
  const [dryRunResult, setDryRunResult] = useState<any>(null)

  const fetchData = async () => {
    setLoading(true)
    try {
      const res = await (api as any).request('GET', '/api/admin/marketplace/agents')
      setAgents(res)
    } catch (err) {
      console.error(err)
    } finally {
      setLoading(false)
    }
  }

  const handleDryRun = async (packageUrl: string) => {
    try {
      const res = await (api as any).request('POST', '/api/admin/marketplace/install/dry-run', {
        data: { package_url: packageUrl }
      })
      setDryRunResult(res)
      toast.success("Dry-run concluído com sucesso.")
    } catch (err) {
      toast.error("Falha ao simular instalação.")
    }
  }

  useEffect(() => {
    fetchData()
  }, [])

  return (
    <div className="p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold">Agent Marketplace</h1>
          <p className="text-muted-foreground">Instale agentes de terceiros com governança e segurança</p>
        </div>
        <Button variant="outline">
          <Download className="w-4 h-4 mr-2" /> Importar Localmente
        </Button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {agents.map((agent) => (
          <Card key={agent.id} className="overflow-hidden border-white/5 bg-slate-900/50 hover:border-blue-500/50 transition-all">
            <CardHeader className="pb-2">
              <div className="flex justify-between items-start">
                <CardTitle className="text-lg">{agent.name}</CardTitle>
                <Badge variant={agent.risk_level === 'low' ? 'secondary' : 'outline'}>
                  {agent.risk_level} risk
                </Badge>
              </div>
              <CardDescription>{agent.description}</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex flex-wrap gap-1">
                {agent.permissions.map((p: string) => (
                  <Badge key={p} variant="secondary" className="text-[10px] py-0">
                    {p}
                  </Badge>
                ))}
              </div>

              <div className="flex items-center gap-2 text-xs">
                {agent.attestation_status === 'verified' ? (
                  <div className="flex items-center text-emerald-400 gap-1">
                    <ShieldCheck size={14} /> Attestation Verified
                  </div>
                ) : (
                  <div className="flex items-center text-orange-400 gap-1">
                    <ShieldAlert size={14} /> Untrusted Source
                  </div>
                )}
              </div>

              <div className="pt-2 flex gap-2">
                <Button 
                  size="sm" 
                  className="flex-1" 
                  onClick={() => handleDryRun(`https://market.stack/packages/${agent.id}`)}
                >
                  Dry-run Install
                </Button>
                <Button size="sm" variant="ghost" className="px-2">
                  <ExternalLink size={14} />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}

        {agents.length === 0 && !loading && (
          <div className="col-span-full py-20 text-center border-2 border-dashed rounded-3xl border-white/5">
             <ShoppingBag className="w-12 h-12 mx-auto text-slate-700 mb-4" />
             <p className="text-muted-foreground">Nenhum agente disponível no marketplace.</p>
          </div>
        )}
      </div>

      {dryRunResult && (
        <Card className="border-blue-500/20 bg-blue-500/5">
          <CardHeader>
            <div className="flex items-center gap-2">
              <Info className="text-blue-400 w-5 h-5" />
              <CardTitle className="text-lg">Resultado da Simulação de Instalação</CardTitle>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="text-sm font-bold mb-2 uppercase text-slate-500">Manifesto</h4>
                <pre className="text-xs p-3 bg-slate-950 rounded-lg overflow-auto max-h-40">
                  {JSON.stringify(dryRunResult.manifest, null, 2)}
                </pre>
              </div>
              <div>
                <h4 className="text-sm font-bold mb-2 uppercase text-slate-500">Avaliação de Política</h4>
                <div className="p-3 bg-slate-950 rounded-lg space-y-3">
                   <div className="flex justify-between items-center">
                     <span>Status:</span>
                     <Badge variant={dryRunResult.policy_evaluation === 'allowed' ? 'secondary' : 'destructive'}>
                       {dryRunResult.policy_evaluation}
                     </Badge>
                   </div>
                   {dryRunResult.warnings.map((w: string, i: number) => (
                     <div key={i} className="text-xs text-orange-400 flex items-start gap-2">
                       <ShieldAlert size={12} className="mt-0.5" /> {w}
                     </div>
                   ))}
                </div>
              </div>
            </div>
            <div className="flex justify-end pt-4">
              <Button onClick={() => setDryRunResult(null)} variant="ghost" className="mr-2">Cancelar</Button>
              <Button disabled={dryRunResult.policy_evaluation === 'blocked'}>Aprovar e Instalar</Button>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  )
}

import { useState, type ReactNode } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Activity, Bot, Clock, Coins, Download, Play, ShieldCheck, Zap } from 'lucide-react'
import { toast } from 'sonner'

import api from '../../lib/api'

export default function AgentObservability() {
  const queryClient = useQueryClient()
  const [selectedRun, setSelectedRun] = useState<string | null>(null)

  const { data: overview } = useQuery({
    queryKey: ['agent-observability-overview'],
    queryFn: () => api.getAgentObservabilityOverview(),
  })

  const { data: metricsSummary } = useQuery({
    queryKey: ['agent-observability-metrics-summary'],
    queryFn: () => api.getAgentObservabilityMetricsSummary(),
  })

  const { data: timeline } = useQuery({
    queryKey: ['agent-observability-timeline', selectedRun],
    queryFn: () => selectedRun ? api.getAgentRunTimeline(selectedRun) : [],
    enabled: !!selectedRun,
  })

  const { data: trace } = useQuery({
    queryKey: ['agent-observability-trace', selectedRun],
    queryFn: () => selectedRun ? api.getAgentRunTrace(selectedRun) : null,
    enabled: !!selectedRun,
  })

  const { data: telemetryStatus } = useQuery({
    queryKey: ['agent-observability-telemetry-status'],
    queryFn: () => api.getAgentTelemetryStatus(),
  })

  const replayMutation = useMutation({
    mutationFn: (runId: string) => api.replayAgentRun(runId),
    onSuccess: () => toast.success('Replay agendado com sucesso.'),
    onError: (error: any) => toast.error(error?.message || 'Falha ao iniciar replay'),
  })

  const exportTraceMutation = useMutation({
    mutationFn: () => api.exportAgentTrace(trace),
    onSuccess: result => {
      const blob = new Blob([JSON.stringify(result, null, 2)], { type: 'application/json' })
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `agent-trace-${selectedRun || 'unknown'}.json`
      a.click()
      toast.success('Trace exportado.')
    },
    onError: (error: any) => toast.error(error?.message || 'Falha ao exportar trace'),
  })

  const recentRuns = Array.isArray(overview?.recent_runs) ? overview.recent_runs : []

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-2xl md:text-3xl font-bold text-foreground">Agent Observability</h1>
        <p className="text-sm md:text-lg text-muted-foreground">Overview, timeline, trace, telemetry status e replay reais.</p>
      </div>

      <div className="grid grid-cols-2 gap-3 lg:grid-cols-4">
        <MetricCard label="Total Runs" value={String(overview?.total_runs || 0)} icon={<Bot className="h-5 w-5" />} />
        <MetricCard label="Avg Latency" value={`${Number(metricsSummary?.avg_step_latency_ms || 0).toFixed(0)}ms`} icon={<Clock className="h-5 w-5 text-primary" />} />
        <MetricCard label="Tokens" value={Number(metricsSummary?.total_tokens || 0).toLocaleString()} icon={<Zap className="h-5 w-5" />} />
        <MetricCard label="Cost" value={`R$ ${Number(metricsSummary?.total_cost_brl || 0).toFixed(2)}`} icon={<Coins className="h-5 w-5 text-emerald-500" />} />
      </div>

      <div className="grid gap-6 xl:grid-cols-[1fr,1fr]">
        <Card title="Recent Runs">
          <table className="min-w-full text-sm">
            <thead>
              <tr className="border-b border-border text-left text-xs font-black uppercase tracking-widest text-muted-foreground">
                <th className="py-3 pr-4">Run</th>
                <th className="py-3 pr-4">Agent</th>
                <th className="py-3 pr-4">Status</th>
                <th className="py-3 pr-4">Steps</th>
                <th className="py-3 pr-4"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {recentRuns.map((run: any) => (
                <tr key={run.id}>
                  <td className="py-3 pr-4 font-mono text-xs text-muted-foreground">{String(run.id).slice(0, 12)}</td>
                  <td className="py-3 pr-4 text-foreground">{String(run.agent_id).slice(0, 12)}</td>
                  <td className="py-3 pr-4 text-foreground">{run.status}</td>
                  <td className="py-3 pr-4 text-foreground">{run.total_steps}</td>
                  <td className="py-3 pr-4">
                    <button type="button" onClick={() => setSelectedRun(run.id)} className="rounded-lg border border-border px-3 py-1 text-xs font-bold hover:bg-secondary">
                      Selecionar
                    </button>
                  </td>
                </tr>
              ))}
              {!recentRuns.length && (
                <tr><td colSpan={5} className="py-8 text-center text-muted-foreground">Nenhuma execucao recente.</td></tr>
              )}
            </tbody>
          </table>
        </Card>

        <Card title="Telemetry Status">
          <div className="space-y-4">
            <SummaryRow label="OTel tracing" value={telemetryStatus?.otel_tracing_enabled ? 'enabled' : 'disabled'} />
            <SummaryRow label="LangSmith export" value={telemetryStatus?.langsmith_export_enabled ? 'enabled' : 'disabled'} />
            <div className="rounded-2xl bg-background p-4 text-sm text-muted-foreground">
              Selecione um run para timeline, trace, replay e export.
            </div>
          </div>
        </Card>
      </div>

      {selectedRun && (
        <div className="grid gap-6 xl:grid-cols-[1fr,1fr]">
          <Card title={`Timeline ${selectedRun.slice(0, 12)}`}>
            <JsonList values={timeline || []} />
          </Card>
          <Card title="Trace">
            <div className="mb-4 flex gap-3">
              <button type="button" onClick={() => replayMutation.mutate(selectedRun)} className="rounded-xl border border-border px-4 py-2 text-sm font-bold hover:bg-secondary">
                <Play className="mr-2 inline h-4 w-4" />
                Replay
              </button>
              <button type="button" onClick={() => exportTraceMutation.mutate()} disabled={!trace} className="rounded-xl bg-primary px-4 py-2 text-sm font-bold text-white hover:bg-primary/90 disabled:opacity-50">
                <Download className="mr-2 inline h-4 w-4" />
                Exportar
              </button>
            </div>
            <pre className="overflow-x-auto rounded-2xl bg-background p-3 text-[10px] text-foreground">
              {JSON.stringify(trace || {}, null, 2)}
            </pre>
          </Card>
        </div>
      )}
    </div>
  )
}

function MetricCard({ label, value, icon }: { label: string; value: string; icon: ReactNode }) {
  return (
    <div className="rounded-2xl border border-border bg-card p-4 shadow-sm">
      <div className="mb-2 flex items-center gap-3 text-muted-foreground">{icon}</div>
      <div className="text-[10px] font-black uppercase tracking-widest text-muted-foreground">{label}</div>
      <div className="text-2xl font-black text-foreground">{value}</div>
    </div>
  )
}

function Card({ title, children }: { title: string; children: ReactNode }) {
  return (
    <section className="rounded-3xl border border-border bg-card p-5 shadow-sm">
      <div className="mb-4 text-lg font-black text-foreground">{title}</div>
      {children}
    </section>
  )
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-center justify-between rounded-2xl border border-border bg-background px-4 py-3">
      <span className="text-sm text-muted-foreground">{label}</span>
      <span className="text-sm font-black text-foreground">{value}</span>
    </div>
  )
}

function JsonList({ values }: { values: any[] }) {
  return (
    <div className="space-y-3">
      {values.length ? values.map((value, index) => (
        <pre key={index} className="overflow-x-auto rounded-2xl bg-background p-3 text-[10px] text-foreground">
          {JSON.stringify(value, null, 2)}
        </pre>
      )) : (
        <div className="rounded-2xl border border-dashed border-border p-6 text-sm text-muted-foreground">Nenhum registro.</div>
      )}
    </div>
  )
}

