import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../../lib/api'
import { Check, Info, AlertTriangle } from 'lucide-react'
import { useState } from 'react'
import { toast } from 'sonner'

export default function TuningProfiles() {
  const queryClient = useQueryClient()
  const [selectedProfile, setSelectedProfile] = useState<string | null>(null)

  const { data: profiles, isLoading } = useQuery({
    queryKey: ['tuning-profiles'],
    queryFn: async () => {
      const res = await api.get('/admin/performance/profiles')
      return res.data
    }
  })

  const applyMutation = useMutation({
    mutationFn: async (profileName: string) => {
      return api.post(`/admin/performance/apply-profile?profile_name=${profileName}`)
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ['tuning-profiles'] })
      queryClient.invalidateQueries({ queryKey: ['current-profile'] })
      toast.success(`Perfil aplicado: ${data.data.profile}${data.data.advisory ? ' (MODO ADVISORY)' : ''}`)
    }
  })

  const seedMutation = useMutation({
    mutationFn: async () => api.post('/admin/performance/seed-profiles'),
    onSuccess: () => {
      toast.success('Perfis padrão inicializados')
      queryClient.invalidateQueries({ queryKey: ['tuning-profiles'] })
    },
    onError: () => {
      toast.error('Falha ao inicializar perfis padrão')
    }
  })

  if (isLoading) return <div className="p-8">Carregando perfis...</div>

  return (
    <div className="max-w-7xl mx-auto px-4 py-8">
      <div className="mb-10 flex flex-col gap-4 md:flex-row md:items-end md:justify-between">
        <div>
          <h1 className="text-3xl font-black text-foreground mb-2">Perfis de <span className="text-primary">Runtime Tuning</span></h1>
          <p className="text-muted-foreground font-medium">Configure como o sistema prioriza recursos e responde à carga.</p>
        </div>
        <button
          onClick={() => seedMutation.mutate()}
          disabled={seedMutation.isPending}
          className="bg-secondary text-foreground font-bold px-4 py-2.5 rounded-2xl hover:bg-secondary/80 transition-colors disabled:opacity-50"
        >
          {seedMutation.isPending ? 'Inicializando...' : 'Inicializar perfis padrão'}
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {profiles?.map((p: any) => (
          <div 
            key={p.name} 
            className={`bg-card border-2 rounded-3xl p-6 transition-all cursor-pointer ${p.is_active ? 'border-primary shadow-lg shadow-teal-500/10' : 'border-border hover:border-border'}`}
            onClick={() => setSelectedProfile(p.name)}
          >
            <div className="flex justify-between items-start mb-4">
              <div className={`p-3 rounded-2xl ${p.is_active ? 'bg-primary/10 text-primary' : 'bg-secondary text-muted-foreground'}`}>
                {p.is_active ? <Check className="w-6 h-6" /> : <Info className="w-6 h-6" />}
              </div>
              {p.is_active && (
                <span className="bg-primary text-background text-[10px] font-black px-2 py-1 rounded-full uppercase tracking-tighter">Ativo</span>
              )}
            </div>
            <h3 className="text-xl font-bold text-foreground mb-1 uppercase tracking-tight">{p.name.replace(/_/g, ' ')}</h3>
            <p className="text-sm text-muted-foreground mb-6 h-10 overflow-hidden">{p.description}</p>

            <div className="space-y-3 mb-8">
              {Object.entries(p.config).map(([key, val]: [string, any]) => (
                <div key={key} className="flex justify-between text-[10px] font-bold uppercase tracking-wider">
                  <span className="text-muted-foreground">{key.replace(/_/g, ' ')}</span>
                  <span className="text-foreground">{val.toString()}</span>
                </div>
              ))}
            </div>

            <button 
              onClick={(e) => {
                e.stopPropagation()
                applyMutation.mutate(p.name)
              }}
              disabled={p.is_active || applyMutation.isPending}
              className={`w-full py-3 rounded-2xl font-bold text-sm transition-all ${p.is_active ? 'bg-secondary text-muted-foreground cursor-not-allowed' : 'bg-foreground text-background hover:bg-primary'}`}
            >
              {p.is_active ? 'Perfil Atual' : 'Aplicar Perfil'}
            </button>
          </div>
        ))}
      </div>

      <div className="mt-12 p-8 bg-yellow-500/10 border border-amber-100 rounded-3xl flex items-start gap-4">
        <AlertTriangle className="w-6 h-6 text-yellow-600 shrink-0" />
        <div>
          <h4 className="font-bold text-amber-900 mb-1">Modo de Aplicação de Tuning</h4>
          <p className="text-sm text-yellow-600 leading-relaxed">
            Por padrão, a aplicação de perfis é **ADVISORY**. O sistema registra a intenção e os eventos, mas não altera as variáveis de ambiente reais do container. 
            Para permitir mudanças reais, defina <code className="bg-yellow-500/20 px-1 rounded font-bold">RUNTIME_TUNING_APPLY_ENABLED=true</code>.
          </p>
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '../../components/card'
import { Button } from '../../components/button'
import api from '../../lib/api'
import { FileText, FolderOpen, Plus, Trash2 } from 'lucide-react'
import { toast } from 'sonner'

export default function Rag() {
  const [collections, setCollections] = useState<any[]>([])
  const [usage, setUsage] = useState<any>(null)
  const [loading, setLoading] = useState(true)

  const fetchData = async () => {
    try {
      const [cols, u] = await Promise.all([
        api.listRagCollections().catch(() => []),
        api.getRagUsage().catch(() => null),
      ])
      setCollections(cols)
      setUsage(u)
    } catch {}
    setLoading(false)
  }

  useEffect(() => { fetchData() }, [])

  const handleCreate = async () => {
    const name = prompt('Nome da coleção:')
    if (!name) return
    try {
      await api.createRagCollection({ name })
      toast.success('Coleção criada')
      fetchData()
    } catch { toast.error('Falha ao criar') }
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">RAG</h1>
          <p className="text-muted-foreground">Retrieval-Augmented Generation - gerencie coleções e documentos</p>
        </div>
        <Button onClick={handleCreate}><Plus className="w-4 h-4 mr-2" /> Nova Coleção</Button>
      </div>

      {usage && (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <Card><CardContent className="flex items-center gap-3 p-4"><FileText className="w-8 h-8 text-blue-500" /><div><p className="text-sm text-muted-foreground">Total de Documentos</p><p className="text-2xl font-bold">{usage.total_documents ?? 0}</p></div></CardContent></Card>
          <Card><CardContent className="flex items-center gap-3 p-4"><FolderOpen className="w-8 h-8 text-green-500" /><div><p className="text-sm text-muted-foreground">Coleções</p><p className="text-2xl font-bold">{collections.length}</p></div></CardContent></Card>
        </div>
      )}

      <Card><CardHeader><CardTitle>Coleções</CardTitle></CardHeader>
        <CardContent>
          {loading ? <p>Carregando...</p> : (
            <div className="space-y-3">
              {collections.map(c => (
                <Card key={c.id}><CardContent className="flex items-center justify-between p-4">
                  <div className="flex items-center gap-3"><FolderOpen className="w-5 h-5 text-muted-foreground" /><div><p className="font-medium">{c.name}</p><p className="text-sm text-muted-foreground">{c.document_count ?? 0} documentos</p></div></div>
                </CardContent></Card>
              ))}
              {collections.length === 0 && <p className="text-muted-foreground text-center py-8">Nenhuma coleção encontrada.</p>}
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import api from '../../lib/api'
import { UserCheck, Shield, Key, History, Plus, UserPlus, ShieldAlert, CheckCircle2, Copy } from 'lucide-react'
import { useState } from 'react'
import { Modal } from '../../components/modal'
import { toast } from 'sonner'

function CreateAdminModal({ open, onOpenChange, roles }: { open: boolean, onOpenChange: (open: boolean) => void, roles: any[] }) {
  const queryClient = useQueryClient()
  const [formData, setFormData] = useState({ username: '', email: '', display_name: '', role_ids: [] as string[] })
  const [issuedToken, setIssuedToken] = useState<string | null>(null)

  const mutation = useMutation({
    mutationFn: (data: any) => api.createRbacUser(data),
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ['rbac-users'] })
      setIssuedToken(data.admin_token)
      toast.success('Administrador criado com sucesso!')
    },
    onError: (err: any) => {
      toast.error(err.message || 'Erro ao criar administrador')
    }
  })

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    mutation.mutate(formData)
  }

  const handleClose = () => {
    onOpenChange(false)
    setIssuedToken(null)
    setFormData({ username: '', email: '', display_name: '', role_ids: [] })
    mutation.reset()
  }

  if (issuedToken) {
    return (
      <Modal open={open} onOpenChange={handleClose} title="Token Gerado" description="Copie o token abaixo. Ele não será exibido novamente.">
        <div className="space-y-4">
          <div className="p-4 bg-muted rounded-2xl flex items-center justify-between gap-4 font-mono text-sm break-all border border-border">
            <span>{issuedToken}</span>
            <button 
              onClick={() => { navigator.clipboard.writeText(issuedToken); toast.info('Token copiado!') }}
              className="p-2 hover:bg-background rounded-lg transition-colors"
            >
              <Copy className="w-4 h-4" />
            </button>
          </div>
          <button onClick={handleClose} className="w-full bg-foreground text-background py-3 rounded-2xl font-bold">
            Entendido, fechar
          </button>
        </div>
      </Modal>
    )
  }

  return (
    <Modal open={open} onOpenChange={onOpenChange} title="Novo Administrador" description="Crie um novo usuário com acesso administrativo.">
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Username</label>
          <input 
            className="w-full bg-muted border border-border rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-primary/50"
            value={formData.username}
            onChange={e => setFormData({ ...formData, username: e.target.value })}
            required
            placeholder="ex: admin_joao"
          />
        </div>
        <div className="space-y-2">
          <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Nome Completo</label>
          <input 
            className="w-full bg-muted border border-border rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-primary/50"
            value={formData.display_name}
            onChange={e => setFormData({ ...formData, display_name: e.target.value })}
            required
            placeholder="ex: João Silva"
          />
        </div>
        <div className="space-y-2">
          <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Email</label>
          <input 
            className="w-full bg-muted border border-border rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-primary/50"
            type="email"
            value={formData.email}
            onChange={e => setFormData({ ...formData, email: e.target.value })}
            placeholder="ex: joao@empresa.com"
          />
        </div>
        <div className="space-y-2">
          <label className="text-xs font-black uppercase tracking-widest text-muted-foreground">Cargos</label>
          <div className="grid grid-cols-2 gap-2">
            {roles?.map(role => (
              <label key={role.id} className="flex items-center gap-2 p-3 bg-muted rounded-xl cursor-pointer hover:bg-primary/5 transition-colors border border-border">
                <input 
                  type="checkbox"
                  checked={formData.role_ids.includes(role.id)}
                  onChange={e => {
                    const ids = e.target.checked 
                      ? [...formData.role_ids, role.id]
                      : formData.role_ids.filter(id => id !== role.id)
                    setFormData({ ...formData, role_ids: ids })
                  }}
                />
                <span className="text-xs font-bold">{role.name}</span>
              </label>
            ))}
          </div>
        </div>
        <button 
          disabled={mutation.isPending}
          className="w-full bg-primary text-primary-foreground py-3 rounded-2xl font-bold mt-4 hover:opacity-90 transition-all disabled:opacity-50"
        >
          {mutation.isPending ? 'Criando...' : 'Criar Administrador'}
        </button>
      </form>
    </Modal>
  )
}

